export const FEEDBACK_BANK_ID = [{"id":1,"chapter":"Ch 1 - Penjumlahan & Pengurangan","question":"x + 7 = 15","correctAnswer":"x = 8","code":"OP","errorType":"Operasi invers keliru","wrongAnswers":"22","reason":"Menjumlahkan 15 + 7: memakai operasi yang sama, bukan kebalikannya.","feedback":"Hampir! Di ruas kiri, x sedang ditambah 7. Operasi apa yang bisa 'membatalkan' tambah 7 supaya x sendirian? Lakukan juga di ruas kanan."},{"id":1,"chapter":"Ch 1 - Penjumlahan & Pengurangan","question":"x + 7 = 15","correctAnswer":"x = 8","code":"HT","errorType":"Kesalahan hitung","wrongAnswers":"7 atau 9","reason":"Langkah sudah benar (15 - 7), tetapi hasil pengurangannya salah hitung.","feedback":"Langkahmu sudah tepat! Tinggal teliti hasil pengurangannya. Coba hitung ulang pelan-pelan."},{"id":1,"chapter":"Ch 1 - Penjumlahan & Pengurangan","question":"x + 7 = 15","correctAnswer":"x = 8","code":"LM","errorType":"Langkah belum lengkap","wrongAnswers":"15","reason":"Menganggap bilangan di ruas kanan langsung menjadi nilai x, tanpa menyingkirkan + 7.","feedback":"Coba uji jawabanmu: kalau x = 15, apakah x + 7 benar-benar sama dengan 15? Masih ada bilangan yang belum kamu singkirkan dari x."},{"id":2,"chapter":"Ch 1 - Penjumlahan & Pengurangan","question":"y - 9 = 4","correctAnswer":"y = 13","code":"OP","errorType":"Operasi invers keliru","wrongAnswers":"-5","reason":"Mengurangi 4 dengan 9: mengulang operasi yang sama (- 9), bukan kebalikannya.","feedback":"Di ruas kiri, y dikurangi 9. Supaya y sendirian, 9 itu harus 'dikembalikan'. Operasi apa yang bisa melakukannya? Lakukan juga di ruas kanan."},{"id":2,"chapter":"Ch 1 - Penjumlahan & Pengurangan","question":"y - 9 = 4","correctAnswer":"y = 13","code":"TD","errorType":"Kesalahan tanda / urutan","wrongAnswers":"5","reason":"Mengurangkan bilangan kecil dari bilangan besar (9 - 4), mengabaikan bilangan mana yang menjadi titik awal.","feedback":"Perhatikan urutannya. Di ruas kanan ada 4, dan 9 'pindah' ke sana dengan operasi kebalikan. Tulis ulang langkahmu mulai dari 4."},{"id":2,"chapter":"Ch 1 - Penjumlahan & Pengurangan","question":"y - 9 = 4","correctAnswer":"y = 13","code":"HT","errorType":"Kesalahan hitung","wrongAnswers":"12 atau 14","reason":"Langkah sudah benar (4 + 9), tetapi hasil penjumlahannya salah hitung.","feedback":"Langkahmu sudah tepat! Tinggal teliti hasil penjumlahannya. Coba hitung ulang."},{"id":3,"chapter":"Ch 1 - Penjumlahan & Pengurangan","question":"a + 12 = 5","correctAnswer":"a = -7","code":"TD","errorType":"Kesalahan tanda / urutan","wrongAnswers":"7","reason":"Menghitung 12 - 5 (bilangan kecil dikurangkan dari yang besar) sehingga tanda negatif hilang.","feedback":"Kamu sudah mengurangi dengan benar! Sekarang periksa tandanya: 5 dikurangi 12 hasilnya positif atau negatif? Bayangkan garis bilangan."},{"id":3,"chapter":"Ch 1 - Penjumlahan & Pengurangan","question":"a + 12 = 5","correctAnswer":"a = -7","code":"OP","errorType":"Operasi invers keliru","wrongAnswers":"17","reason":"Menjumlahkan 5 + 12: mengulang operasi yang sama.","feedback":"Di ruas kiri, 12 ditambahkan pada a. Kalau di ruas kanan kamu menambah lagi, 12 tidak akan hilang dari a. Operasi apa yang berlawanan dengan tambah?"},{"id":3,"chapter":"Ch 1 - Penjumlahan & Pengurangan","question":"a + 12 = 5","correctAnswer":"a = -7","code":"HT","errorType":"Kesalahan hitung","wrongAnswers":"-6 atau -8","reason":"Langkah benar (5 - 12), tetapi hasilnya salah hitung.","feedback":"Langkahmu sudah benar! Hitung ulang hasilnya: dari 5, mundur 12 langkah di garis bilangan, berhenti di mana?"},{"id":4,"chapter":"Ch 1 - Penjumlahan & Pengurangan","question":"m - 15 = -8","correctAnswer":"m = 7","code":"OP","errorType":"Operasi invers keliru","wrongAnswers":"-23","reason":"Mengurangi -8 dengan 15: mengulang operasi yang sama.","feedback":"Di ruas kiri, m dikurangi 15. Untuk mengembalikan m sendirian, operasi apa yang harus kamu lakukan pada kedua ruas?"},{"id":4,"chapter":"Ch 1 - Penjumlahan & Pengurangan","question":"m - 15 = -8","correctAnswer":"m = 7","code":"TD","errorType":"Kesalahan tanda / urutan","wrongAnswers":"-7","reason":"Sudah menambah 15, tetapi menghitung -8 + 15 sebagai -(15 - 8): terpengaruh tanda negatif.","feedback":"Kamu sudah menambah 15, bagus! Sekarang periksa -8 + 15: mulai dari -8 lalu maju 15 langkah. Berhenti di bilangan positif atau negatif?"},{"id":4,"chapter":"Ch 1 - Penjumlahan & Pengurangan","question":"m - 15 = -8","correctAnswer":"m = 7","code":"TD","errorType":"Kesalahan tanda / urutan","wrongAnswers":"23","reason":"Mengabaikan tanda negatif pada -8 (menghitung 8 + 15).","feedback":"Jangan lupa tanda pada ruas kanan: bilangannya -8, bukan 8. Tulis ulang langkahmu dengan tanda negatifnya."},{"id":5,"chapter":"Ch 1 - Penjumlahan & Pengurangan","question":"18 + x = 30","correctAnswer":"x = 12","code":"OP","errorType":"Operasi invers keliru","wrongAnswers":"48","reason":"Menjumlahkan 30 + 18: mengulang operasi yang sama.","feedback":"Di ruas kiri, 18 ditambahkan pada x. Operasi apa yang bisa menyingkirkan 18? Lakukan di kedua ruas."},{"id":5,"chapter":"Ch 1 - Penjumlahan & Pengurangan","question":"18 + x = 30","correctAnswer":"x = 12","code":"TD","errorType":"Kesalahan tanda / urutan","wrongAnswers":"-12","reason":"Membalik urutan pengurangan (18 - 30).","feedback":"Hampir! Periksa urutan pengurangannya: bilangan yang disingkirkan dari ruas kanan adalah 18, jadi 30 dikurangi berapa?"},{"id":5,"chapter":"Ch 1 - Penjumlahan & Pengurangan","question":"18 + x = 30","correctAnswer":"x = 12","code":"HT","errorType":"Kesalahan hitung","wrongAnswers":"11 atau 13","reason":"Langkah benar (30 - 18), tetapi hasilnya salah hitung.","feedback":"Langkahmu sudah tepat! Tinggal teliti hasil pengurangan 30 - 18."},{"id":6,"chapter":"Ch 1 - Penjumlahan & Pengurangan","question":"p - 6,5 = 3,5","correctAnswer":"p = 10","code":"OP","errorType":"Operasi invers keliru","wrongAnswers":"-3","reason":"Mengurangi 3,5 dengan 6,5: mengulang operasi yang sama.","feedback":"Di ruas kiri, p dikurangi 6,5. Untuk mengembalikan p, operasi apa yang harus dilakukan pada kedua ruas?"},{"id":6,"chapter":"Ch 1 - Penjumlahan & Pengurangan","question":"p - 6,5 = 3,5","correctAnswer":"p = 10","code":"PC","errorType":"Pecahan / desimal","wrongAnswers":"9 atau 9,1","reason":"Langkah benar (3,5 + 6,5), tetapi salah menjumlahkan desimal: 0,5 + 0,5 tidak 'disimpan' ke bilangan bulat, atau ditulis 9,10.","feedback":"Langkahmu sudah benar! Teliti lagi penjumlahan desimalnya: 0,5 + 0,5 sama dengan berapa, dan ke mana 'simpanannya' pergi?"},{"id":7,"chapter":"Ch 1 - Penjumlahan & Pengurangan","question":"k + 1/2 = 3","correctAnswer":"k = 5/2 atau 2,5","code":"OP","errorType":"Operasi invers keliru","wrongAnswers":"3,5","reason":"Menjumlahkan 3 + 1/2: mengulang operasi yang sama.","feedback":"Di ruas kiri, 1/2 ditambahkan pada k. Operasi apa yang berlawanan dengan tambah? Lakukan di kedua ruas."},{"id":7,"chapter":"Ch 1 - Penjumlahan & Pengurangan","question":"k + 1/2 = 3","correctAnswer":"k = 5/2 atau 2,5","code":"PC","errorType":"Pecahan / desimal","wrongAnswers":"1","reason":"Menghitung 3 - 1/2 sebagai (3 - 1)/2 = 1.","feedback":"Langkah pengurangannya sudah tepat! Tetapi 3 - 1/2 tidak bisa dihitung seperti itu. Ubah 3 menjadi pecahan berpenyebut 2 dulu, baru kurangi."},{"id":7,"chapter":"Ch 1 - Penjumlahan & Pengurangan","question":"k + 1/2 = 3","correctAnswer":"k = 5/2 atau 2,5","code":"PC","errorType":"Pecahan / desimal","wrongAnswers":"2","reason":"Mengabaikan pecahan 1/2 saat memindah ruas (3 - 1).","feedback":"Pecahan 1/2 ikut dipindah juga, dan nilainya tetap harus dihitung. Berapakah 3 - 1/2? Tulis sebagai bilangan campuran dulu kalau perlu."},{"id":8,"chapter":"Ch 1 - Penjumlahan & Pengurangan","question":"-7 + n = 14","correctAnswer":"n = 21","code":"OP","errorType":"Operasi invers keliru","wrongAnswers":"7","reason":"Mengurangi 14 dengan 7: memindah -7 tanpa membalik operasinya.","feedback":"-7 di ruas kiri artinya n sedang dikurangi 7. Supaya -7 hilang, operasi apa yang harus kamu lakukan pada kedua ruas?"},{"id":8,"chapter":"Ch 1 - Penjumlahan & Pengurangan","question":"-7 + n = 14","correctAnswer":"n = 21","code":"TD","errorType":"Kesalahan tanda / urutan","wrongAnswers":"-21","reason":"Menjumlahkan 14 + 7 dengan benar, tetapi menambahkan tanda negatif pada hasil.","feedback":"Penjumlahannya sudah tepat! Sekarang cek tandanya: uji jawabanmu, apakah -7 + (jawabanmu) benar-benar sama dengan 14?"},{"id":8,"chapter":"Ch 1 - Penjumlahan & Pengurangan","question":"-7 + n = 14","correctAnswer":"n = 21","code":"HT","errorType":"Kesalahan hitung","wrongAnswers":"20 atau 22","reason":"Langkah benar (14 + 7), tetapi hasilnya salah hitung.","feedback":"Langkahmu sudah benar! Tinggal teliti hasil 14 + 7."},{"id":9,"chapter":"Ch 1 - Penjumlahan & Pengurangan","question":"x - 14 = -20","correctAnswer":"x = -6","code":"OP","errorType":"Operasi invers keliru","wrongAnswers":"-34","reason":"Mengurangi -20 dengan 14: mengulang operasi yang sama.","feedback":"Di ruas kiri, x dikurangi 14. Operasi apa yang bisa 'mengembalikan' 14? Lakukan di kedua ruas."},{"id":9,"chapter":"Ch 1 - Penjumlahan & Pengurangan","question":"x - 14 = -20","correctAnswer":"x = -6","code":"TD","errorType":"Kesalahan tanda / urutan","wrongAnswers":"6","reason":"Menghitung -20 + 14 tetapi hasilnya ditulis positif: tanda negatif hilang.","feedback":"Kamu sudah menambah 14 dengan benar! Periksa tanda hasilnya: mulai dari -20, maju 14 langkah. Berhenti di positif atau negatif?"},{"id":9,"chapter":"Ch 1 - Penjumlahan & Pengurangan","question":"x - 14 = -20","correctAnswer":"x = -6","code":"TD","errorType":"Kesalahan tanda / urutan","wrongAnswers":"34","reason":"Mengabaikan tanda negatif pada -20 (menghitung 20 + 14).","feedback":"Tanda negatif pada -20 tidak boleh hilang. Tulis ulang ruas kananmu dengan tanda yang benar."},{"id":9,"chapter":"Ch 1 - Penjumlahan & Pengurangan","question":"x - 14 = -20","correctAnswer":"x = -6","code":"HT","errorType":"Kesalahan hitung","wrongAnswers":"-5 atau -7","reason":"Langkah benar (-20 + 14), tetapi hasilnya salah hitung.","feedback":"Langkahmu sudah tepat! Hitung ulang -20 + 14 pada garis bilangan."},{"id":10,"chapter":"Ch 1 - Penjumlahan & Pengurangan","question":"y + 25 = 11","correctAnswer":"y = -14","code":"TD","errorType":"Kesalahan tanda / urutan","wrongAnswers":"14","reason":"Menghitung 25 - 11 (urutan terbalik) sehingga tanda negatif hilang.","feedback":"Kamu sudah mengurangi 25, bagus! Tapi urutannya: 11 dikurangi 25, bukan sebaliknya. Hasilnya positif atau negatif?"},{"id":10,"chapter":"Ch 1 - Penjumlahan & Pengurangan","question":"y + 25 = 11","correctAnswer":"y = -14","code":"OP","errorType":"Operasi invers keliru","wrongAnswers":"36","reason":"Menjumlahkan 11 + 25: mengulang operasi yang sama.","feedback":"Di ruas kiri, 25 ditambahkan pada y. Operasi apa yang berlawanan dengan tambah? Lakukan di kedua ruas."},{"id":10,"chapter":"Ch 1 - Penjumlahan & Pengurangan","question":"y + 25 = 11","correctAnswer":"y = -14","code":"HT","errorType":"Kesalahan hitung","wrongAnswers":"-13 atau -15","reason":"Langkah benar (11 - 25), tetapi hasilnya salah hitung.","feedback":"Langkahmu sudah tepat! Hitung ulang 11 - 25: dari 11, mundur 25 langkah."},{"id":11,"chapter":"Ch 2 - Perkalian & Pembagian","question":"4x = 28","correctAnswer":"x = 7","code":"KV","errorType":"Keliru kali/bagi","wrongAnswers":"112","reason":"Mengalikan 28 x 4: mengira cara menyingkirkan 4 adalah mengalikan.","feedback":"4x artinya 4 kali x. Supaya x sendirian, operasi apa yang berlawanan dengan 'dikali 4'?"},{"id":11,"chapter":"Ch 2 - Perkalian & Pembagian","question":"4x = 28","correctAnswer":"x = 7","code":"KV","errorType":"Keliru kali/bagi","wrongAnswers":"1/7 (≈ 0,14)","reason":"Membagi 4 dengan 28: urutan pembagian terbalik.","feedback":"Kamu sudah memilih pembagian, bagus! Tapi urutannya tertukar: yang dibagi adalah bilangan di ruas kanan, dan pembaginya koefisien x."},{"id":11,"chapter":"Ch 2 - Perkalian & Pembagian","question":"4x = 28","correctAnswer":"x = 7","code":"OP","errorType":"Operasi invers keliru","wrongAnswers":"24","reason":"Menganggap 4x = 4 + x, lalu mengurangi 28 dengan 4.","feedback":"4x bukan 4 + x, melainkan 4 kali x. Uji jawabanmu: apakah 4 kali jawabanmu sama dengan 28?"},{"id":11,"chapter":"Ch 2 - Perkalian & Pembagian","question":"4x = 28","correctAnswer":"x = 7","code":"HT","errorType":"Kesalahan hitung","wrongAnswers":"6 atau 8","reason":"Langkah benar (28 : 4), tetapi hasil bagi salah hitung.","feedback":"Langkahmu sudah tepat! Tinggal teliti hasil pembagian 28 : 4."},{"id":12,"chapter":"Ch 2 - Perkalian & Pembagian","question":"-3y = 21","correctAnswer":"y = -7","code":"TD","errorType":"Kesalahan tanda / urutan","wrongAnswers":"7","reason":"Membagi 21 : 3 dengan mengabaikan tanda negatif pada -3.","feedback":"Bagus, kamu membagi! Tapi bagilah dengan -3 (bukan 3). Bilangan positif dibagi bilangan negatif, hasilnya positif atau negatif?"},{"id":12,"chapter":"Ch 2 - Perkalian & Pembagian","question":"-3y = 21","correctAnswer":"y = -7","code":"KV","errorType":"Keliru kali/bagi","wrongAnswers":"-63","reason":"Mengalikan 21 x (-3): mengira cara menyingkirkan -3 adalah mengalikan.","feedback":"-3y artinya -3 kali y. Supaya y sendirian, operasi apa yang berlawanan dengan kali?"},{"id":12,"chapter":"Ch 2 - Perkalian & Pembagian","question":"-3y = 21","correctAnswer":"y = -7","code":"OP","errorType":"Operasi invers keliru","wrongAnswers":"24 atau 18","reason":"Menganggap -3y = -3 + y, lalu menambah/mengurang 21 dengan 3.","feedback":"-3y bukan -3 + y, melainkan -3 kali y. Operasi lawan dari 'kali' adalah ...?"},{"id":12,"chapter":"Ch 2 - Perkalian & Pembagian","question":"-3y = 21","correctAnswer":"y = -7","code":"HT","errorType":"Kesalahan hitung","wrongAnswers":"-6 atau -8","reason":"Langkah benar (21 : -3), tetapi hasil bagi salah hitung.","feedback":"Langkahmu sudah tepat! Tinggal teliti hasil pembagiannya."},{"id":13,"chapter":"Ch 2 - Perkalian & Pembagian","question":"a/5 = 6","correctAnswer":"a = 30","code":"KV","errorType":"Keliru kali/bagi","wrongAnswers":"1,2","reason":"Membagi 6 : 5: mengira cara menyingkirkan 'dibagi 5' adalah membagi lagi.","feedback":"Di soal, a sedang dibagi 5. Supaya a sendirian, operasi kebalikan dari 'dibagi 5' adalah ...? Lakukan di kedua ruas."},{"id":13,"chapter":"Ch 2 - Perkalian & Pembagian","question":"a/5 = 6","correctAnswer":"a = 30","code":"OP","errorType":"Operasi invers keliru","wrongAnswers":"1 atau 11","reason":"Menganggap a/5 = a - 5 (atau a + 5), lalu menambah/mengurang 6 dengan 5.","feedback":"a/5 bukan berarti a dikurang 5. Artinya a dibagi 5. Apa kebalikan dari 'dibagi'?"},{"id":13,"chapter":"Ch 2 - Perkalian & Pembagian","question":"a/5 = 6","correctAnswer":"a = 30","code":"HT","errorType":"Kesalahan hitung","wrongAnswers":"25 atau 35","reason":"Langkah benar (6 x 5), tetapi hasil kali salah hitung.","feedback":"Langkahmu sudah tepat! Tinggal teliti hasil perkalian 6 x 5."},{"id":14,"chapter":"Ch 2 - Perkalian & Pembagian","question":"m/4 = -9","correctAnswer":"m = -36","code":"TD","errorType":"Kesalahan tanda / urutan","wrongAnswers":"36","reason":"Mengalikan -9 x 4 tetapi hasilnya ditulis positif: tanda negatif hilang.","feedback":"Kamu sudah mengalikan 4, bagus! Periksa tandanya: -9 dikali 4 hasilnya positif atau negatif?"},{"id":14,"chapter":"Ch 2 - Perkalian & Pembagian","question":"m/4 = -9","correctAnswer":"m = -36","code":"KV","errorType":"Keliru kali/bagi","wrongAnswers":"-2,25","reason":"Membagi -9 : 4: mengira cara menyingkirkan '/4' adalah membagi lagi.","feedback":"m sedang dibagi 4. Supaya m sendirian, operasi kebalikan dari 'dibagi 4' adalah ...?"},{"id":14,"chapter":"Ch 2 - Perkalian & Pembagian","question":"m/4 = -9","correctAnswer":"m = -36","code":"OP","errorType":"Operasi invers keliru","wrongAnswers":"-5 atau -13","reason":"Menganggap m/4 = m - 4, lalu menambah/mengurang -9 dengan 4.","feedback":"m/4 bukan berarti m dikurang 4. Artinya m dibagi 4. Apa kebalikan dari 'dibagi'?"},{"id":15,"chapter":"Ch 2 - Perkalian & Pembagian","question":"(2/3)x = 12","correctAnswer":"x = 18","code":"KV","errorType":"Keliru kali/bagi","wrongAnswers":"8","reason":"Mengalikan 12 x 2/3: memakai pecahan yang sama, bukan kebalikannya.","feedback":"Koefisien x adalah 2/3. Supaya x sendirian, kalikan dengan KEBALIKAN dari 2/3, yaitu pecahan yang pembilang dan penyebutnya ditukar."},{"id":15,"chapter":"Ch 2 - Perkalian & Pembagian","question":"(2/3)x = 12","correctAnswer":"x = 18","code":"LM","errorType":"Langkah belum lengkap","wrongAnswers":"6","reason":"Hanya membagi 12 dengan 2 (pembilang) lalu berhenti, lupa mengalikan 3.","feedback":"Kamu baru menangani angka 2-nya. Masih ada 3 sebagai penyebut. Gunakan kebalikan dari 2/3 sekaligus."},{"id":15,"chapter":"Ch 2 - Perkalian & Pembagian","question":"(2/3)x = 12","correctAnswer":"x = 18","code":"LM","errorType":"Langkah belum lengkap","wrongAnswers":"36","reason":"Hanya mengalikan 12 dengan 3 (penyebut), lupa membagi 2.","feedback":"Kamu baru menangani angka 3-nya. Masih ada 2 sebagai pembilang. Gunakan kebalikan dari 2/3 sekaligus."},{"id":16,"chapter":"Ch 2 - Perkalian & Pembagian","question":"-8p = -56","correctAnswer":"p = 7","code":"TD","errorType":"Kesalahan tanda / urutan","wrongAnswers":"-7","reason":"Membagi -56 : 8 dengan mengabaikan tanda negatif pada pembagi (-8).","feedback":"Bagus, kamu membagi! Periksa tandanya: bilangan negatif dibagi bilangan negatif, hasilnya positif atau negatif?"},{"id":16,"chapter":"Ch 2 - Perkalian & Pembagian","question":"-8p = -56","correctAnswer":"p = 7","code":"KV","errorType":"Keliru kali/bagi","wrongAnswers":"448","reason":"Mengalikan -56 x (-8): mengira cara menyingkirkan -8 adalah mengalikan.","feedback":"-8p artinya -8 kali p. Supaya p sendirian, operasi apa yang berlawanan dengan kali?"},{"id":16,"chapter":"Ch 2 - Perkalian & Pembagian","question":"-8p = -56","correctAnswer":"p = 7","code":"OP","errorType":"Operasi invers keliru","wrongAnswers":"-64 atau -48","reason":"Menganggap -8p = -8 + p, lalu menambah/mengurang -56 dengan 8.","feedback":"-8p bukan -8 + p, melainkan -8 kali p. Operasi lawan dari 'kali' adalah ...?"},{"id":16,"chapter":"Ch 2 - Perkalian & Pembagian","question":"-8p = -56","correctAnswer":"p = 7","code":"HT","errorType":"Kesalahan hitung","wrongAnswers":"6 atau 8","reason":"Langkah benar (-56 : -8), tetapi hasil bagi salah hitung.","feedback":"Langkahmu sudah tepat! Tinggal teliti hasil pembagian 56 : 8."},{"id":17,"chapter":"Ch 2 - Perkalian & Pembagian","question":"y/0,5 = 14","correctAnswer":"y = 7","code":"KV","errorType":"Keliru kali/bagi","wrongAnswers":"28","reason":"Membagi 14 : 0,5: mengira cara menyingkirkan '/0,5' adalah membagi lagi.","feedback":"y sudah dibagi 0,5. Supaya y sendirian, operasi kebalikan dari 'dibagi' adalah ...?"},{"id":17,"chapter":"Ch 2 - Perkalian & Pembagian","question":"y/0,5 = 14","correctAnswer":"y = 7","code":"PC","errorType":"Pecahan / desimal","wrongAnswers":"70 atau 0,7","reason":"Mengalikan 14 x 0,5 dengan letak koma salah pada hasil.","feedback":"Kamu sudah mengalikan, langkah yang tepat! Periksa letak komanya: apakah wajar 14 dikali bilangan kurang dari 1 hasilnya sebesar itu?"},{"id":17,"chapter":"Ch 2 - Perkalian & Pembagian","question":"y/0,5 = 14","correctAnswer":"y = 7","code":"OP","errorType":"Operasi invers keliru","wrongAnswers":"13,5 atau 14,5","reason":"Menganggap y/0,5 = y - 0,5, lalu menambah/mengurang 14 dengan 0,5.","feedback":"y/0,5 artinya y DIBAGI 0,5, bukan dikurangi 0,5. Operasi kebaliknya apa?"},{"id":18,"chapter":"Ch 2 - Perkalian & Pembagian","question":"0,4k = 1,6","correctAnswer":"k = 4","code":"KV","errorType":"Keliru kali/bagi","wrongAnswers":"0,64","reason":"Mengalikan 1,6 x 0,4: mengira cara menyingkirkan 0,4 adalah mengalikan.","feedback":"0,4k artinya 0,4 kali k. Supaya k sendirian, operasi apa yang berlawanan dengan kali?"},{"id":18,"chapter":"Ch 2 - Perkalian & Pembagian","question":"0,4k = 1,6","correctAnswer":"k = 4","code":"PC","errorType":"Pecahan / desimal","wrongAnswers":"0,4 atau 40","reason":"Membagi 1,6 : 0,4 dengan letak koma salah pada hasil.","feedback":"Pembagianmu sudah tepat, periksa letak komanya. Trik: kalikan 1,6 dan 0,4 dengan 10 supaya jadi bilangan bulat, lalu bagi."},{"id":18,"chapter":"Ch 2 - Perkalian & Pembagian","question":"0,4k = 1,6","correctAnswer":"k = 4","code":"KV","errorType":"Keliru kali/bagi","wrongAnswers":"0,25","reason":"Membagi 0,4 : 1,6: urutan pembagian terbalik.","feedback":"Kamu sudah memilih pembagian, bagus! Tapi urutannya tertukar: yang dibagi adalah 1,6 (ruas kanan), dan pembaginya 0,4."},{"id":18,"chapter":"Ch 2 - Perkalian & Pembagian","question":"0,4k = 1,6","correctAnswer":"k = 4","code":"OP","errorType":"Operasi invers keliru","wrongAnswers":"1,2 atau 2","reason":"Menganggap 0,4k = 0,4 + k, lalu menambah/mengurang 1,6 dengan 0,4.","feedback":"0,4k bukan 0,4 + k, melainkan 0,4 kali k. Operasi lawan dari 'kali' adalah ...?"},{"id":19,"chapter":"Ch 2 - Perkalian & Pembagian","question":"-(3/4)n = 15","correctAnswer":"n = -20","code":"TD","errorType":"Kesalahan tanda / urutan","wrongAnswers":"20","reason":"Membagi 15 dengan 3/4 dan mengabaikan tanda negatif pada koefisien -3/4 (hasil ditulis positif).","feedback":"Langkahmu sudah bagus! Periksa tanda di langkah terakhir: koefisiennya -3/4, jadi bilangan positif dikali kebalikan yang negatif hasilnya positif atau negatif?"},{"id":19,"chapter":"Ch 2 - Perkalian & Pembagian","question":"-(3/4)n = 15","correctAnswer":"n = -20","code":"KV","errorType":"Keliru kali/bagi","wrongAnswers":"-11,25 atau 11,25","reason":"Mengalikan 15 x (-3/4) atau 15 x 3/4: memakai pecahan yang sama, bukan kebalikannya.","feedback":"Koefisien n adalah -3/4. Supaya n sendirian, kalikan dengan KEBALIKAN dari -3/4, yaitu pecahan yang pembilang dan penyebutnya ditukar (tanda negatif tetap ada)."},{"id":19,"chapter":"Ch 2 - Perkalian & Pembagian","question":"-(3/4)n = 15","correctAnswer":"n = -20","code":"LM","errorType":"Langkah belum lengkap","wrongAnswers":"-5","reason":"Hanya membagi 15 dengan -3 (pembilang) lalu berhenti, lupa mengalikan 4.","feedback":"Kamu baru menangani angka 3-nya. Masih ada 4 sebagai penyebut. Gunakan kebalikan dari -3/4 sekaligus."},{"id":19,"chapter":"Ch 2 - Perkalian & Pembagian","question":"-(3/4)n = 15","correctAnswer":"n = -20","code":"LM","errorType":"Langkah belum lengkap","wrongAnswers":"60","reason":"Hanya mengalikan 15 dengan 4 (penyebut), lupa membagi -3.","feedback":"Kamu baru menangani angka 4-nya. Masih ada -3 sebagai pembilang. Gunakan kebalikan dari -3/4 sekaligus."},{"id":20,"chapter":"Ch 2 - Perkalian & Pembagian","question":"15z = -75","correctAnswer":"z = -5","code":"TD","errorType":"Kesalahan tanda / urutan","wrongAnswers":"5","reason":"Membagi -75 : 15 tetapi hasilnya ditulis positif: tanda negatif hilang.","feedback":"Kamu sudah membagi 75 dengan 15, bagus! Periksa tandanya: bilangan negatif dibagi bilangan positif, hasilnya positif atau negatif?"},{"id":20,"chapter":"Ch 2 - Perkalian & Pembagian","question":"15z = -75","correctAnswer":"z = -5","code":"KV","errorType":"Keliru kali/bagi","wrongAnswers":"-1125","reason":"Mengalikan -75 x 15: mengira cara menyingkirkan 15 adalah mengalikan.","feedback":"15z artinya 15 kali z. Supaya z sendirian, operasi apa yang berlawanan dengan kali?"},{"id":20,"chapter":"Ch 2 - Perkalian & Pembagian","question":"15z = -75","correctAnswer":"z = -5","code":"KV","errorType":"Keliru kali/bagi","wrongAnswers":"-0,2","reason":"Membagi 15 : (-75): urutan pembagian terbalik.","feedback":"Kamu sudah memilih pembagian, bagus! Tapi urutannya tertukar: yang dibagi adalah -75 (ruas kanan), dan pembaginya 15."},{"id":20,"chapter":"Ch 2 - Perkalian & Pembagian","question":"15z = -75","correctAnswer":"z = -5","code":"HT","errorType":"Kesalahan hitung","wrongAnswers":"-4 atau -6","reason":"Langkah benar (-75 : 15), tetapi hasil bagi salah hitung.","feedback":"Langkahmu sudah tepat! Tinggal teliti hasil pembagian 75 : 15."},{"id":21,"chapter":"Ch 3 - Operasi Campuran","question":"2x + 5 = 17","correctAnswer":"x = 6","code":"LM","errorType":"Langkah belum lengkap","wrongAnswers":"12","reason":"Berhenti di 2x = 12 (belum dibagi 2).","feedback":"Kamu sudah menyingkirkan + 5, bagus! Tapi x belum sendirian: masih ada 2 yang mengalikan x. Lanjutkan!"},{"id":21,"chapter":"Ch 3 - Operasi Campuran","question":"2x + 5 = 17","correctAnswer":"x = 6","code":"OP","errorType":"Operasi invers keliru","wrongAnswers":"11","reason":"Menambah 5 ke ruas kanan (17 + 5) lalu membagi 2.","feedback":"Di ruas kiri, 5 ditambahkan pada 2x. Operasi kebalikan dari 'tambah 5' adalah ...? Lakukan di kedua ruas sebelum membagi 2."},{"id":21,"chapter":"Ch 3 - Operasi Campuran","question":"2x + 5 = 17","correctAnswer":"x = 6","code":"BS","errorType":"Operasi hanya pada sebagian suku","wrongAnswers":"3,5 atau 14,5","reason":"Hanya membagi satu suku (17 : 2 - 5, atau 17 - 5 : 2).","feedback":"Saat membagi 2, SEMUA suku ikut dibagi. Lebih aman: singkirkan + 5 dulu dari kedua ruas, baru bagi dengan 2."},{"id":21,"chapter":"Ch 3 - Operasi Campuran","question":"2x + 5 = 17","correctAnswer":"x = 6","code":"HT","errorType":"Kesalahan hitung","wrongAnswers":"5 atau 7","reason":"Langkah benar (12 : 2), tetapi hasil bagi salah hitung.","feedback":"Langkahmu sudah tepat! Tinggal teliti hasil pembagian 12 : 2."},{"id":22,"chapter":"Ch 3 - Operasi Campuran","question":"3y - 8 = 13","correctAnswer":"y = 7","code":"LM","errorType":"Langkah belum lengkap","wrongAnswers":"21","reason":"Berhenti di 3y = 21 (belum dibagi 3).","feedback":"Kamu sudah menyingkirkan - 8, bagus! Tapi y belum sendirian: masih ada 3 yang mengalikan y. Lanjutkan!"},{"id":22,"chapter":"Ch 3 - Operasi Campuran","question":"3y - 8 = 13","correctAnswer":"y = 7","code":"OP","errorType":"Operasi invers keliru","wrongAnswers":"5/3 (≈ 1,67)","reason":"Mengurangi 13 dengan 8 (mengulang operasi yang sama) lalu membagi 3.","feedback":"Di ruas kiri, 8 sedang dikurangkan. Operasi kebalikan dari 'kurang 8' adalah ...? Lakukan di kedua ruas."},{"id":22,"chapter":"Ch 3 - Operasi Campuran","question":"3y - 8 = 13","correctAnswer":"y = 7","code":"BS","errorType":"Operasi hanya pada sebagian suku","wrongAnswers":"37/3 (≈ 12,33)","reason":"Membagi 13 : 3 lalu menambah 8 (hanya membagi satu suku).","feedback":"Saat membagi 3, SEMUA suku ikut dibagi. Lebih aman: singkirkan - 8 dulu dari kedua ruas, baru bagi dengan 3."},{"id":22,"chapter":"Ch 3 - Operasi Campuran","question":"3y - 8 = 13","correctAnswer":"y = 7","code":"HT","errorType":"Kesalahan hitung","wrongAnswers":"6 atau 8","reason":"Langkah benar (21 : 3), tetapi hasil bagi salah hitung.","feedback":"Langkahmu sudah tepat! Tinggal teliti hasil pembagian 21 : 3."},{"id":23,"chapter":"Ch 3 - Operasi Campuran","question":"5a + 12 = -3","correctAnswer":"a = -3","code":"LM","errorType":"Langkah belum lengkap","wrongAnswers":"-15","reason":"Berhenti di 5a = -15 (belum dibagi 5).","feedback":"Kamu sudah menyingkirkan + 12, bagus! Tapi a masih dikali 5. Lanjutkan sampai a sendirian."},{"id":23,"chapter":"Ch 3 - Operasi Campuran","question":"5a + 12 = -3","correctAnswer":"a = -3","code":"TD","errorType":"Kesalahan tanda / urutan","wrongAnswers":"3","reason":"Membagi -15 : 5 tetapi hasilnya ditulis positif: tanda negatif hilang.","feedback":"Langkahmu sudah bagus! Periksa tanda di langkah terakhir: bilangan negatif dibagi bilangan positif, hasilnya positif atau negatif?"},{"id":23,"chapter":"Ch 3 - Operasi Campuran","question":"5a + 12 = -3","correctAnswer":"a = -3","code":"OP","errorType":"Operasi invers keliru","wrongAnswers":"1,8","reason":"Menambah 12 ke ruas kanan (-3 + 12) lalu membagi 5.","feedback":"Di ruas kiri, 12 ditambahkan pada 5a. Kalau kamu menambah lagi, 12 tidak akan hilang. Operasi lawan dari 'tambah' apa?"},{"id":23,"chapter":"Ch 3 - Operasi Campuran","question":"5a + 12 = -3","correctAnswer":"a = -3","code":"BS","errorType":"Operasi hanya pada sebagian suku","wrongAnswers":"-12,6","reason":"Membagi -3 : 5 lalu mengurangi 12 (hanya membagi satu suku).","feedback":"Saat membagi 5, SEMUA suku ikut dibagi. Lebih aman: singkirkan + 12 dulu dari kedua ruas, baru bagi dengan 5."},{"id":24,"chapter":"Ch 3 - Operasi Campuran","question":"4(m - 2) = 16","correctAnswer":"m = 6","code":"DS","errorType":"Distribusi (membuka kurung) keliru","wrongAnswers":"4,5","reason":"Membuka 4(m - 2) menjadi 4m - 2: angka 2 tidak ikut dikali 4.","feedback":"Ingat: angka di depan kurung mengalikan SEMUA isi kurung. Coba kalikan 4 dengan m, lalu 4 dengan 2."},{"id":24,"chapter":"Ch 3 - Operasi Campuran","question":"4(m - 2) = 16","correctAnswer":"m = 6","code":"DS","errorType":"Distribusi (membuka kurung) keliru","wrongAnswers":"2","reason":"Membuka 4(m - 2) menjadi 4m + 8: tanda negatif hilang saat dikali.","feedback":"Periksa tanda saat membuka kurung: 4 x (-2) hasilnya positif atau negatif?"},{"id":24,"chapter":"Ch 3 - Operasi Campuran","question":"4(m - 2) = 16","correctAnswer":"m = 6","code":"LM","errorType":"Langkah belum lengkap","wrongAnswers":"4","reason":"Berhenti di m - 2 = 4 (belum menambah 2).","feedback":"Kamu sudah membagi 4 dengan benar! Tapi m masih ditemani - 2. Lanjutkan sampai m sendirian."},{"id":24,"chapter":"Ch 3 - Operasi Campuran","question":"4(m - 2) = 16","correctAnswer":"m = 6","code":"KV","errorType":"Keliru kali/bagi","wrongAnswers":"66","reason":"Mengalikan 16 x 4 (bukan membagi) lalu menambah 2.","feedback":"Angka 4 di depan kurung mengalikan isi kurung. Supaya 4 itu hilang, operasi apa yang berlawanan dengan kali?"},{"id":25,"chapter":"Ch 3 - Operasi Campuran","question":"(x + 4)/3 = 5","correctAnswer":"x = 11","code":"LM","errorType":"Langkah belum lengkap","wrongAnswers":"15","reason":"Berhenti di x + 4 = 15 (belum mengurangi 4).","feedback":"Kamu sudah menyingkirkan penyebut 3, bagus! Tapi x masih ditemani + 4. Lanjutkan!"},{"id":25,"chapter":"Ch 3 - Operasi Campuran","question":"(x + 4)/3 = 5","correctAnswer":"x = 11","code":"BS","errorType":"Operasi hanya pada sebagian suku","wrongAnswers":"11/3 (≈ 3,67)","reason":"Menganggap hanya 4 yang dibagi 3: x + 4/3 = 5.","feedback":"Perhatikan garis pecahannya: (x + 4) SELURUHNYA dibagi 3, bukan hanya 4-nya. Saat ruas kiri dikali 3, apa yang terjadi pada bagian atas?"},{"id":25,"chapter":"Ch 3 - Operasi Campuran","question":"(x + 4)/3 = 5","correctAnswer":"x = 11","code":"OP","errorType":"Operasi invers keliru","wrongAnswers":"19","reason":"Mengalikan 5 x 3 lalu menambah 4 (seharusnya dikurangi).","feedback":"Di ruas kiri, 4 ditambahkan pada x. Operasi kebalikan dari 'tambah 4' adalah ...? Lakukan di kedua ruas."},{"id":25,"chapter":"Ch 3 - Operasi Campuran","question":"(x + 4)/3 = 5","correctAnswer":"x = 11","code":"HT","errorType":"Kesalahan hitung","wrongAnswers":"10 atau 12","reason":"Langkah benar (15 - 4), tetapi hasilnya salah hitung.","feedback":"Langkahmu sudah tepat! Tinggal teliti hasil 15 - 4."},{"id":26,"chapter":"Ch 3 - Operasi Campuran","question":"-2p + 9 = 25","correctAnswer":"p = -8","code":"TD","errorType":"Kesalahan tanda / urutan","wrongAnswers":"8","reason":"Membagi 16 : 2 dengan mengabaikan tanda negatif pada koefisien -2.","feedback":"Hampir! Kamu sudah membagi 16 dengan 2. Tapi koefisiennya -2, bukan 2. Positif dibagi negatif hasilnya ...?"},{"id":26,"chapter":"Ch 3 - Operasi Campuran","question":"-2p + 9 = 25","correctAnswer":"p = -8","code":"OP","errorType":"Operasi invers keliru","wrongAnswers":"-17","reason":"Menambah 9 ke ruas kanan (25 + 9) lalu membagi -2.","feedback":"Di ruas kiri, 9 ditambahkan pada -2p. Operasi kebalikan dari 'tambah 9' adalah ...? Lakukan di kedua ruas."},{"id":26,"chapter":"Ch 3 - Operasi Campuran","question":"-2p + 9 = 25","correctAnswer":"p = -8","code":"LM","errorType":"Langkah belum lengkap","wrongAnswers":"16","reason":"Berhenti di -2p = 16 (belum dibagi -2).","feedback":"Bagus, kamu sudah menyingkirkan + 9! Tapi p masih dikali -2. Lanjutkan sampai p sendirian."},{"id":26,"chapter":"Ch 3 - Operasi Campuran","question":"-2p + 9 = 25","correctAnswer":"p = -8","code":"KV","errorType":"Keliru kali/bagi","wrongAnswers":"-32","reason":"Mengalikan 16 x (-2): mengira cara menyingkirkan -2 adalah mengalikan.","feedback":"-2p artinya -2 kali p. Supaya p sendirian, operasi apa yang berlawanan dengan kali?"},{"id":27,"chapter":"Ch 3 - Operasi Campuran","question":"7 - 3k = -11","correctAnswer":"k = 6","code":"TD","errorType":"Kesalahan tanda / urutan","wrongAnswers":"-6","reason":"Membagi -18 : (-3) tetapi hasilnya ditulis negatif.","feedback":"Langkahmu sudah bagus! Periksa tanda di langkah terakhir: negatif dibagi negatif hasilnya positif atau negatif?"},{"id":27,"chapter":"Ch 3 - Operasi Campuran","question":"7 - 3k = -11","correctAnswer":"k = 6","code":"PR","errorType":"Pindah ruas keliru","wrongAnswers":"4/3 (≈ 1,33)","reason":"Menyingkirkan 7 dengan -11 + 7: tanda 7 tidak berubah saat pindah ruas.","feedback":"Saat 7 pindah ke ruas kanan, tandanya berubah. + 7 di kiri menjadi ... di kanan. Coba lagi langkah pertama."},{"id":27,"chapter":"Ch 3 - Operasi Campuran","question":"7 - 3k = -11","correctAnswer":"k = 6","code":"GS","errorType":"Menggabungkan suku tidak sejenis","wrongAnswers":"-2,75","reason":"Menggabungkan 7 - 3k menjadi 4k (mengurangi suku tidak sejenis).","feedback":"7 dan 3k bukan suku sejenis: 7 bilangan biasa, 3k memuat k. Keduanya tidak bisa digabung jadi 4k. Singkirkan 7 dulu dari kedua ruas."},{"id":27,"chapter":"Ch 3 - Operasi Campuran","question":"7 - 3k = -11","correctAnswer":"k = 6","code":"LM","errorType":"Langkah belum lengkap","wrongAnswers":"-18","reason":"Berhenti di -3k = -18 (belum dibagi -3).","feedback":"Hampir selesai! k masih dikali -3. Lanjutkan sampai k sendirian."},{"id":28,"chapter":"Ch 3 - Operasi Campuran","question":"2y/5 - 3 = 7","correctAnswer":"y = 25","code":"LM","errorType":"Langkah belum lengkap","wrongAnswers":"50","reason":"Berhenti di 2y = 50 (belum dibagi 2).","feedback":"Kamu sudah menghilangkan penyebut 5, bagus! Tapi y masih dikali 2. Lanjutkan!"},{"id":28,"chapter":"Ch 3 - Operasi Campuran","question":"2y/5 - 3 = 7","correctAnswer":"y = 25","code":"KV","errorType":"Keliru kali/bagi","wrongAnswers":"4","reason":"Mengalikan 10 dengan 2/5 (bukan kebalikannya 5/2).","feedback":"Untuk menghilangkan pembagi 5, kalikan 5 ke kedua ruas. Setelah itu baru urus angka 2 di depan y."},{"id":28,"chapter":"Ch 3 - Operasi Campuran","question":"2y/5 - 3 = 7","correctAnswer":"y = 25","code":"PR","errorType":"Pindah ruas keliru","wrongAnswers":"10","reason":"Memindah -3 tanpa mengubah tanda (2y/5 = 7 - 3).","feedback":"Saat - 3 pindah ke ruas kanan, tandanya berubah. Coba lagi langkah pertamamu."},{"id":28,"chapter":"Ch 3 - Operasi Campuran","question":"2y/5 - 3 = 7","correctAnswer":"y = 25","code":"HT","errorType":"Kesalahan hitung","wrongAnswers":"20 atau 30","reason":"Langkah benar (2y = 50), tetapi 50 : 2 salah hitung.","feedback":"Langkahmu sudah tepat! Tinggal teliti hasil pembagian 50 : 2."},{"id":29,"chapter":"Ch 3 - Operasi Campuran","question":"3(2n + 1) = 27","correctAnswer":"n = 4","code":"DS","errorType":"Distribusi (membuka kurung) keliru","wrongAnswers":"13/3 (≈ 4,33)","reason":"Membuka 3(2n + 1) menjadi 6n + 1: angka 1 tidak ikut dikali 3.","feedback":"Ingat: angka di depan kurung mengalikan SEMUA isi kurung. Coba kalikan 3 dengan 2n, lalu 3 dengan 1."},{"id":29,"chapter":"Ch 3 - Operasi Campuran","question":"3(2n + 1) = 27","correctAnswer":"n = 4","code":"LM","errorType":"Langkah belum lengkap","wrongAnswers":"8","reason":"Berhenti di 2n = 8 (belum dibagi 2).","feedback":"Kamu sudah menyingkirkan + 1, bagus! Tapi n masih dikali 2. Lanjutkan!"},{"id":29,"chapter":"Ch 3 - Operasi Campuran","question":"3(2n + 1) = 27","correctAnswer":"n = 4","code":"LM","errorType":"Langkah belum lengkap","wrongAnswers":"9","reason":"Berhenti di 2n + 1 = 9 (belum menyingkirkan + 1 dan 2).","feedback":"Kamu sudah menghilangkan 3 di depan kurung, bagus! Tapi n masih ditemani + 1 dan dikali 2. Lanjutkan!"},{"id":29,"chapter":"Ch 3 - Operasi Campuran","question":"3(2n + 1) = 27","correctAnswer":"n = 4","code":"PR","errorType":"Pindah ruas keliru","wrongAnswers":"5","reason":"Memindah + 1 tanpa mengubah tanda (2n = 9 + 1).","feedback":"Saat + 1 pindah ke ruas kanan, tandanya berubah. Coba lagi langkahmu."},{"id":30,"chapter":"Ch 3 - Operasi Campuran","question":"10 - 2(x + 3) = 2","correctAnswer":"x = 1","code":"DS","errorType":"Distribusi (membuka kurung) keliru","wrongAnswers":"7","reason":"Membuka -2(x + 3) menjadi -2x + 6: tanda negatif tidak ikut dikali.","feedback":"Periksa tanda saat membuka kurung: -2 dikali + 3 hasilnya positif atau negatif?"},{"id":30,"chapter":"Ch 3 - Operasi Campuran","question":"10 - 2(x + 3) = 2","correctAnswer":"x = 1","code":"DS","errorType":"Distribusi (membuka kurung) keliru","wrongAnswers":"2,5","reason":"Membuka -2(x + 3) menjadi -2x - 3: angka 3 tidak ikut dikali 2.","feedback":"Ingat: angka di depan kurung (termasuk tandanya) mengalikan SEMUA isi kurung. Coba kalikan -2 dengan x, lalu -2 dengan 3."},{"id":30,"chapter":"Ch 3 - Operasi Campuran","question":"10 - 2(x + 3) = 2","correctAnswer":"x = 1","code":"GS","errorType":"Menggabungkan suku tidak sejenis","wrongAnswers":"-2,75","reason":"Mengurangi 10 - 2 = 8 lebih dulu sehingga menjadi 8(x + 3) = 2.","feedback":"Hati-hati urutan operasinya: 2(x + 3) harus dikerjakan dulu (perkalian) sebelum dikurangkan dari 10."},{"id":30,"chapter":"Ch 3 - Operasi Campuran","question":"10 - 2(x + 3) = 2","correctAnswer":"x = 1","code":"TD","errorType":"Kesalahan tanda / urutan","wrongAnswers":"-1","reason":"Menyelesaikan -2x = -2 menjadi x = -1: negatif dibagi negatif dianggap negatif.","feedback":"Langkahmu sudah bagus! Periksa tanda di langkah terakhir: negatif dibagi negatif hasilnya positif atau negatif?"},{"id":31,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"5x - 3 = 2x + 9","correctAnswer":"x = 4","code":"PR","errorType":"Pindah ruas keliru","wrongAnswers":"2","reason":"5x - 2x = 9 - 3: memindah -3 tanpa mengubah tanda.","feedback":"Saat - 3 pindah ke ruas kanan, tandanya berubah. - 3 di kiri menjadi ... di kanan. Coba lagi."},{"id":31,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"5x - 3 = 2x + 9","correctAnswer":"x = 4","code":"PR","errorType":"Pindah ruas keliru","wrongAnswers":"12/7 (≈ 1,71)","reason":"5x + 2x = 9 + 3: memindah 2x tanpa mengubah tanda.","feedback":"Saat 2x pindah ke ruas kiri, tandanya juga berubah. + 2x di kanan menjadi ... di kiri. Coba lagi."},{"id":31,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"5x - 3 = 2x + 9","correctAnswer":"x = 4","code":"LM","errorType":"Langkah belum lengkap","wrongAnswers":"12","reason":"Berhenti di 3x = 12 (belum dibagi 3).","feedback":"Kamu berhasil mengumpulkan suku-sukunya, hebat! Tapi x masih dikali 3. Lanjutkan!"},{"id":31,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"5x - 3 = 2x + 9","correctAnswer":"x = 4","code":"HT","errorType":"Kesalahan hitung","wrongAnswers":"3 atau 5","reason":"Langkah benar (12 : 3), tetapi hasil bagi salah hitung.","feedback":"Langkahmu sudah tepat! Tinggal teliti hasil pembagian 12 : 3."},{"id":32,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"7y + 4 = 3y - 12","correctAnswer":"y = -4","code":"PR","errorType":"Pindah ruas keliru","wrongAnswers":"-2","reason":"7y - 3y = -12 + 4: memindah + 4 tanpa mengubah tanda.","feedback":"Saat + 4 pindah ke ruas kanan, tandanya berubah. Coba lagi langkah pemindahanmu."},{"id":32,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"7y + 4 = 3y - 12","correctAnswer":"y = -4","code":"PR","errorType":"Pindah ruas keliru","wrongAnswers":"-1,6","reason":"7y + 3y = -12 - 4: memindah 3y tanpa mengubah tanda.","feedback":"Saat 3y pindah ke ruas kiri, tandanya juga berubah. + 3y di kanan menjadi ... di kiri."},{"id":32,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"7y + 4 = 3y - 12","correctAnswer":"y = -4","code":"TD","errorType":"Kesalahan tanda / urutan","wrongAnswers":"4","reason":"Membagi -16 : 4 tetapi hasilnya ditulis positif: tanda negatif hilang.","feedback":"Kamu sudah membagi, bagus! Periksa tandanya: -16 dibagi 4 hasilnya positif atau negatif?"},{"id":32,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"7y + 4 = 3y - 12","correctAnswer":"y = -4","code":"LM","errorType":"Langkah belum lengkap","wrongAnswers":"-16","reason":"Berhenti di 4y = -16 (belum dibagi 4).","feedback":"Kamu berhasil mengumpulkan suku-sukunya, hebat! Tapi y masih dikali 4. Lanjutkan!"},{"id":33,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"4a + 10 = 6a - 2","correctAnswer":"a = 6","code":"PR","errorType":"Pindah ruas keliru","wrongAnswers":"-4","reason":"4a - 6a = -2 + 10: memindah + 10 tanpa mengubah tanda.","feedback":"Saat + 10 pindah ke ruas kanan, tandanya berubah. Coba lagi langkah pemindahanmu."},{"id":33,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"4a + 10 = 6a - 2","correctAnswer":"a = 6","code":"PR","errorType":"Pindah ruas keliru","wrongAnswers":"-1,2","reason":"4a + 6a = -2 - 10: memindah 6a tanpa mengubah tanda.","feedback":"Saat 6a pindah ke ruas kiri, tandanya juga berubah. + 6a di kanan menjadi ... di kiri."},{"id":33,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"4a + 10 = 6a - 2","correctAnswer":"a = 6","code":"TD","errorType":"Kesalahan tanda / urutan","wrongAnswers":"-6","reason":"Menyelesaikan -2a = -12 menjadi a = -6: negatif dibagi negatif dianggap negatif.","feedback":"Langkahmu sudah bagus! Periksa tanda di langkah terakhir: negatif dibagi negatif hasilnya positif atau negatif?"},{"id":33,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"4a + 10 = 6a - 2","correctAnswer":"a = 6","code":"LM","errorType":"Langkah belum lengkap","wrongAnswers":"12","reason":"Berhenti di 2a = 12 (belum dibagi 2).","feedback":"Kamu berhasil mengumpulkan suku-sukunya, hebat! Tapi a masih dikali 2. Lanjutkan!"},{"id":34,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"3(m + 2) = 2(m + 7)","correctAnswer":"m = 8","code":"DS","errorType":"Distribusi (membuka kurung) keliru","wrongAnswers":"12","reason":"Membuka 3(m + 2) menjadi 3m + 2: angka 2 tidak ikut dikali 3.","feedback":"Ingat: angka di depan kurung mengalikan SEMUA isi kurung. Periksa ruas kiri DAN ruas kananmu."},{"id":34,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"3(m + 2) = 2(m + 7)","correctAnswer":"m = 8","code":"DS","errorType":"Distribusi (membuka kurung) keliru","wrongAnswers":"1","reason":"Membuka 2(m + 7) menjadi 2m + 7: angka 7 tidak ikut dikali 2.","feedback":"Ingat: angka di depan kurung mengalikan SEMUA isi kurung. Periksa ruas kiri DAN ruas kananmu."},{"id":34,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"3(m + 2) = 2(m + 7)","correctAnswer":"m = 8","code":"TD","errorType":"Kesalahan tanda / urutan","wrongAnswers":"-8","reason":"3m - 2m = 6 - 14: urutan pengurangan terbalik.","feedback":"Hampir! Saat memindahkan suku konstan, periksa urutannya: bilangan di ruas kanan dikurangi bilangan yang pindah dari ruas kiri, bukan sebaliknya."},{"id":34,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"3(m + 2) = 2(m + 7)","correctAnswer":"m = 8","code":"PR","errorType":"Pindah ruas keliru","wrongAnswers":"4","reason":"3m + 2m = 14 + 6: memindah 6 dan 2m tanpa mengubah tanda.","feedback":"Saat suku pindah ruas, tandanya berubah. Periksa lagi tanda 6 dan 2m setelah dipindah."},{"id":34,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"3(m + 2) = 2(m + 7)","correctAnswer":"m = 8","code":"HT","errorType":"Kesalahan hitung","wrongAnswers":"7 atau 9","reason":"Langkah benar (14 - 6), tetapi hasilnya salah hitung.","feedback":"Langkahmu sudah tepat! Tinggal teliti hasil 14 - 6."},{"id":35,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"8 - 2p = 4p + 20","correctAnswer":"p = -2","code":"TD","errorType":"Kesalahan tanda / urutan","wrongAnswers":"2","reason":"Membagi -12 : 6 tetapi hasilnya ditulis positif: tanda negatif hilang.","feedback":"Kamu sudah membagi, bagus! Periksa tandanya: -12 dibagi 6 hasilnya positif atau negatif?"},{"id":35,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"8 - 2p = 4p + 20","correctAnswer":"p = -2","code":"PR","errorType":"Pindah ruas keliru","wrongAnswers":"-14/3 (≈ -4,67)","reason":"-2p - 4p = 20 + 8: memindah 8 tanpa mengubah tanda.","feedback":"Saat 8 pindah ke ruas kanan, tandanya berubah. + 8 di kiri menjadi ... di kanan."},{"id":35,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"8 - 2p = 4p + 20","correctAnswer":"p = -2","code":"PR","errorType":"Pindah ruas keliru","wrongAnswers":"6","reason":"8 - 2p + 4p = 20: memindah 4p tanpa mengubah tanda.","feedback":"Saat 4p pindah ke ruas kiri, tandanya juga berubah. + 4p di kanan menjadi ... di kiri."},{"id":35,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"8 - 2p = 4p + 20","correctAnswer":"p = -2","code":"LM","errorType":"Langkah belum lengkap","wrongAnswers":"-12","reason":"Berhenti di -12 = 6p (belum dibagi 6).","feedback":"Kamu berhasil mengumpulkan suku-sukunya, hebat! Tapi p masih dikali 6. Lanjutkan!"},{"id":35,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"8 - 2p = 4p + 20","correctAnswer":"p = -2","code":"GS","errorType":"Menggabungkan suku tidak sejenis","wrongAnswers":"10","reason":"Menggabungkan 8 - 2p menjadi 6p (mengurangi suku tidak sejenis).","feedback":"8 dan 2p bukan suku sejenis: 8 bilangan biasa, 2p memuat p. Keduanya tidak bisa digabung jadi 6p."},{"id":36,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"6k - 5 = 2k + 15","correctAnswer":"k = 5","code":"PR","errorType":"Pindah ruas keliru","wrongAnswers":"2,5","reason":"6k - 2k = 15 - 5: memindah - 5 tanpa mengubah tanda.","feedback":"Saat - 5 pindah ke ruas kanan, tandanya berubah. Coba lagi langkah pemindahanmu."},{"id":36,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"6k - 5 = 2k + 15","correctAnswer":"k = 5","code":"PR","errorType":"Pindah ruas keliru","wrongAnswers":"1,25","reason":"6k + 2k = 15 - 5: memindah 2k dan - 5 tanpa mengubah tanda.","feedback":"Saat suku pindah ruas, tandanya berubah. Periksa lagi tanda 2k dan 5 setelah dipindah."},{"id":36,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"6k - 5 = 2k + 15","correctAnswer":"k = 5","code":"LM","errorType":"Langkah belum lengkap","wrongAnswers":"20","reason":"Berhenti di 4k = 20 (belum dibagi 4).","feedback":"Kamu berhasil mengumpulkan suku-sukunya, hebat! Tapi k masih dikali 4. Lanjutkan!"},{"id":36,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"6k - 5 = 2k + 15","correctAnswer":"k = 5","code":"KV","errorType":"Keliru kali/bagi","wrongAnswers":"80","reason":"Mengalikan 20 x 4 (bukan membagi).","feedback":"4k artinya 4 kali k. Supaya k sendirian, operasi apa yang berlawanan dengan kali?"},{"id":36,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"6k - 5 = 2k + 15","correctAnswer":"k = 5","code":"HT","errorType":"Kesalahan hitung","wrongAnswers":"4 atau 6","reason":"Langkah benar (20 : 4), tetapi hasil bagi salah hitung.","feedback":"Langkahmu sudah tepat! Tinggal teliti hasil pembagian 20 : 4."},{"id":37,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"(1/2)x + 3 = (1/4)x + 5","correctAnswer":"x = 8","code":"KV","errorType":"Keliru kali/bagi","wrongAnswers":"0,5","reason":"Mengalikan 2 x 1/4: memakai pecahan yang sama, bukan kebalikannya.","feedback":"Koefisien x adalah 1/4. Supaya x sendirian, kalikan dengan KEBALIKAN dari 1/4."},{"id":37,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"(1/2)x + 3 = (1/4)x + 5","correctAnswer":"x = 8","code":"PC","errorType":"Pecahan / desimal","wrongAnswers":"-4","reason":"Mengurangkan 1/2 - 1/4 dengan mengurangi penyebut (1/(2-4) = -1/2), sehingga - 1/2 x = 2.","feedback":"Mengurangi pecahan tidak dilakukan pada penyebutnya! Samakan penyebutnya dulu (jadikan perempat), baru kurangi pembilangnya."},{"id":37,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"(1/2)x + 3 = (1/4)x + 5","correctAnswer":"x = 8","code":"PR","errorType":"Pindah ruas keliru","wrongAnswers":"8/3 (≈ 2,67)","reason":"1/2 x + 1/4 x = 2: memindah 1/4 x tanpa mengubah tanda.","feedback":"Saat 1/4 x pindah ke ruas kiri, tandanya juga berubah. + 1/4 x di kanan menjadi ... di kiri."},{"id":37,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"(1/2)x + 3 = (1/4)x + 5","correctAnswer":"x = 8","code":"PR","errorType":"Pindah ruas keliru","wrongAnswers":"32","reason":"1/2 x - 1/4 x = 5 + 3: memindah + 3 tanpa mengubah tanda.","feedback":"Saat + 3 pindah ke ruas kanan, tandanya berubah. + 3 di kiri menjadi ... di kanan."},{"id":37,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"(1/2)x + 3 = (1/4)x + 5","correctAnswer":"x = 8","code":"LM","errorType":"Langkah belum lengkap","wrongAnswers":"2","reason":"Berhenti di 1/4 x = 2 (belum dikali 4).","feedback":"Kamu berhasil mengumpulkan suku-sukunya, hebat! Tapi x masih dikali 1/4. Lanjutkan!"},{"id":38,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"5(n - 1) = 3(n + 3)","correctAnswer":"n = 7","code":"DS","errorType":"Distribusi (membuka kurung) keliru","wrongAnswers":"5","reason":"Membuka 5(n - 1) menjadi 5n - 1: angka 1 tidak ikut dikali 5.","feedback":"Ingat: angka di depan kurung mengalikan SEMUA isi kurung. Periksa ruas kiri DAN ruas kananmu."},{"id":38,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"5(n - 1) = 3(n + 3)","correctAnswer":"n = 7","code":"DS","errorType":"Distribusi (membuka kurung) keliru","wrongAnswers":"4","reason":"Membuka 3(n + 3) menjadi 3n + 3: angka 3 (kedua) tidak ikut dikali 3.","feedback":"Ingat: angka di depan kurung mengalikan SEMUA isi kurung. Periksa ruas kiri DAN ruas kananmu."},{"id":38,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"5(n - 1) = 3(n + 3)","correctAnswer":"n = 7","code":"DS","errorType":"Distribusi (membuka kurung) keliru","wrongAnswers":"2","reason":"Membuka 5(n - 1) menjadi 5n + 5: tanda negatif hilang saat dikali.","feedback":"Periksa tanda saat membuka kurung: 5 x (-1) hasilnya positif atau negatif?"},{"id":38,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"5(n - 1) = 3(n + 3)","correctAnswer":"n = 7","code":"PR","errorType":"Pindah ruas keliru","wrongAnswers":"0,5","reason":"5n + 3n = 9 - 5: memindah 3n dan - 5 tanpa mengubah tanda.","feedback":"Saat suku pindah ruas, tandanya berubah. Periksa lagi tanda 3n dan 5 setelah dipindah."},{"id":38,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"5(n - 1) = 3(n + 3)","correctAnswer":"n = 7","code":"HT","errorType":"Kesalahan hitung","wrongAnswers":"6 atau 8","reason":"Langkah benar (14 : 2), tetapi hasil bagi salah hitung.","feedback":"Langkahmu sudah tepat! Tinggal teliti hasil pembagian 14 : 2."},{"id":39,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"9x - (2x + 5) = 3x + 11","correctAnswer":"x = 4","code":"DS","errorType":"Distribusi (membuka kurung) keliru","wrongAnswers":"1,5","reason":"Membuka -(2x + 5) menjadi - 2x + 5: tanda pada 5 tidak berubah.","feedback":"Tanda minus di depan kurung berlaku untuk SEMUA isi kurung, termasuk 5. Coba buka kurung sekali lagi."},{"id":39,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"9x - (2x + 5) = 3x + 11","correctAnswer":"x = 4","code":"DS","errorType":"Distribusi (membuka kurung) keliru","wrongAnswers":"2","reason":"Membuka -(2x + 5) menjadi + 2x - 5: tanda pada 2x tidak berubah.","feedback":"Tanda minus di depan kurung berlaku untuk SEMUA isi kurung, termasuk 2x. Coba buka kurung sekali lagi."},{"id":39,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"9x - (2x + 5) = 3x + 11","correctAnswer":"x = 4","code":"LM","errorType":"Langkah belum lengkap","wrongAnswers":"16","reason":"Berhenti di 4x = 16 (belum dibagi 4).","feedback":"Kamu berhasil mengumpulkan suku-sukunya, hebat! Tapi x masih dikali 4. Lanjutkan!"},{"id":39,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"9x - (2x + 5) = 3x + 11","correctAnswer":"x = 4","code":"HT","errorType":"Kesalahan hitung","wrongAnswers":"3 atau 5","reason":"Langkah benar (16 : 4), tetapi hasil bagi salah hitung.","feedback":"Langkahmu sudah tepat! Tinggal teliti hasil pembagian 16 : 4."},{"id":40,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"4(2z - 1) = 2(3z + 5)","correctAnswer":"z = 7","code":"DS","errorType":"Distribusi (membuka kurung) keliru","wrongAnswers":"5,5","reason":"Membuka 4(2z - 1) menjadi 8z - 1: angka 1 tidak ikut dikali 4.","feedback":"Ingat: angka di depan kurung mengalikan SEMUA isi kurung. Periksa ruas kiri DAN ruas kananmu."},{"id":40,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"4(2z - 1) = 2(3z + 5)","correctAnswer":"z = 7","code":"DS","errorType":"Distribusi (membuka kurung) keliru","wrongAnswers":"4,5","reason":"Membuka 2(3z + 5) menjadi 6z + 5: angka 5 tidak ikut dikali 2.","feedback":"Ingat: angka di depan kurung mengalikan SEMUA isi kurung. Periksa ruas kiri DAN ruas kananmu."},{"id":40,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"4(2z - 1) = 2(3z + 5)","correctAnswer":"z = 7","code":"DS","errorType":"Distribusi (membuka kurung) keliru","wrongAnswers":"3","reason":"Membuka 4(2z - 1) menjadi 8z + 4: tanda negatif hilang saat dikali.","feedback":"Periksa tanda saat membuka kurung: 4 x (-1) hasilnya positif atau negatif?"},{"id":40,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"4(2z - 1) = 2(3z + 5)","correctAnswer":"z = 7","code":"PR","errorType":"Pindah ruas keliru","wrongAnswers":"1","reason":"8z + 6z - 4 = 10: memindah 6z tanpa mengubah tanda.","feedback":"Saat 6z pindah ke ruas kiri, tandanya berubah. + 6z di kanan menjadi ... di kiri."},{"id":40,"chapter":"Ch 4 - Variabel di Kedua Ruas","question":"4(2z - 1) = 2(3z + 5)","correctAnswer":"z = 7","code":"LM","errorType":"Langkah belum lengkap","wrongAnswers":"14","reason":"Berhenti di 2z = 14 (belum dibagi 2).","feedback":"Kamu berhasil mengumpulkan suku-sukunya, hebat! Tapi z masih dikali 2. Lanjutkan!"},{"id":41,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Kain Batik Parang - Jawa) Harga 3 lembar kain batik Parang setelah mendapat diskon voucher Rp20.000,00 adalah Rp250.000,00. Berapakah harga awal 1 lembar kain batik Parang?","correctAnswer":"Rp90.000,00","code":"MP","errorType":"Model persamaan salah (soal cerita)","wrongAnswers":"Rp83.333,33","reason":"Mengabaikan diskon: 250.000 : 3.","feedback":"Baca lagi: Rp250.000 adalah harga SETELAH diskon, jadi harga awalnya lebih tinggi. Bagaimana menulis 'harga awal 3 lembar dikurangi diskon = 250.000' sebagai persamaan?"},{"id":41,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Kain Batik Parang - Jawa) Harga 3 lembar kain batik Parang setelah mendapat diskon voucher Rp20.000,00 adalah Rp250.000,00. Berapakah harga awal 1 lembar kain batik Parang?","correctAnswer":"Rp90.000,00","code":"MP","errorType":"Model persamaan salah (soal cerita)","wrongAnswers":"Rp76.666,67","reason":"Mengurangi diskon dari harga akhir: (250.000 - 20.000) : 3.","feedback":"Harga setelah diskon lebih murah dari harga awal. Untuk kembali ke harga awal, diskon harus diapakan, dikurangi lagi atau dikembalikan?"},{"id":41,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Kain Batik Parang - Jawa) Harga 3 lembar kain batik Parang setelah mendapat diskon voucher Rp20.000,00 adalah Rp250.000,00. Berapakah harga awal 1 lembar kain batik Parang?","correctAnswer":"Rp90.000,00","code":"MP","errorType":"Model persamaan salah (soal cerita)","wrongAnswers":"Rp103.333,33","reason":"Menganggap diskon berlaku per lembar: x - 20.000 = 250.000 : 3.","feedback":"Diskon Rp20.000 berlaku untuk seluruh pembelian (3 lembar), bukan tiap lembar. Di bagian mana persamaanmu seharusnya diskon itu ditulis?"},{"id":41,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Kain Batik Parang - Jawa) Harga 3 lembar kain batik Parang setelah mendapat diskon voucher Rp20.000,00 adalah Rp250.000,00. Berapakah harga awal 1 lembar kain batik Parang?","correctAnswer":"Rp90.000,00","code":"LM","errorType":"Langkah belum lengkap","wrongAnswers":"Rp270.000","reason":"Berhenti di 3x = 270.000 (harga awal 3 lembar), lupa membagi 3.","feedback":"Bagus, persamaanmu sudah benar! Tapi 270.000 itu harga awal untuk 3 lembar. Yang ditanyakan adalah harga awal 1 lembar."},{"id":42,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Candi Borobudur - Jawa Tengah) Jumlah batu pada tingkatan bawah 15 buah lebih banyak daripada tingkatan atas. Jika total batu kedua tingkatan 85 buah, berapakah jumlah batu pada tingkatan atas?","correctAnswer":"35 batu","code":"MP","errorType":"Model persamaan salah (soal cerita)","wrongAnswers":"42,5","reason":"Membagi total 85 : 2: menganggap kedua tingkatan sama banyak.","feedback":"Kedua tingkatan tidak sama banyak! Tingkatan bawah punya 15 batu lebih. Jika atas = x, bagaimana menuliskan batu tingkat bawah?"},{"id":42,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Candi Borobudur - Jawa Tengah) Jumlah batu pada tingkatan bawah 15 buah lebih banyak daripada tingkatan atas. Jika total batu kedua tingkatan 85 buah, berapakah jumlah batu pada tingkatan atas?","correctAnswer":"35 batu","code":"PT","errorType":"Menjawab besaran lain","wrongAnswers":"50","reason":"Menjawab jumlah batu tingkat bawah, atau memodelkan atas = bawah + 15.","feedback":"Periksa pertanyaannya: yang dicari tingkatan atas atau bawah? Cek juga siapa yang lebih banyak, atas atau bawah?"},{"id":42,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Candi Borobudur - Jawa Tengah) Jumlah batu pada tingkatan bawah 15 buah lebih banyak daripada tingkatan atas. Jika total batu kedua tingkatan 85 buah, berapakah jumlah batu pada tingkatan atas?","correctAnswer":"35 batu","code":"LM","errorType":"Langkah belum lengkap","wrongAnswers":"70","reason":"Berhenti di 2x = 70 (belum dibagi 2).","feedback":"Kamu sudah mengurus + 15, bagus! Tapi 2x bukan jawabannya: x masih dikali 2. Lanjutkan!"},{"id":43,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Angklung - Jawa Barat) Harga angklung besar Rp15.000,00 lebih mahal daripada angklung kecil. Pembeli membayar Rp105.000,00 untuk 2 angklung kecil dan 1 angklung besar. Berapakah harga 1 angklung kecil?","correctAnswer":"Rp30.000,00","code":"PT","errorType":"Menjawab besaran lain","wrongAnswers":"Rp45.000","reason":"Menjawab harga angklung besar (x + 15.000).","feedback":"Kamu sudah menemukan harga salah satu angklung, tetapi periksa pertanyaannya: yang ditanyakan angklung kecil atau besar?"},{"id":43,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Angklung - Jawa Barat) Harga angklung besar Rp15.000,00 lebih mahal daripada angklung kecil. Pembeli membayar Rp105.000,00 untuk 2 angklung kecil dan 1 angklung besar. Berapakah harga 1 angklung kecil?","correctAnswer":"Rp30.000,00","code":"MP","errorType":"Model persamaan salah (soal cerita)","wrongAnswers":"Rp35.000","reason":"Membagi 105.000 : 3: menganggap ketiga angklung berharga sama.","feedback":"Angklung besar tidak sama harganya dengan yang kecil (lebih mahal Rp15.000). Jangan abaikan selisih itu saat menyusun persamaan."},{"id":43,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Angklung - Jawa Barat) Harga angklung besar Rp15.000,00 lebih mahal daripada angklung kecil. Pembeli membayar Rp105.000,00 untuk 2 angklung kecil dan 1 angklung besar. Berapakah harga 1 angklung kecil?","correctAnswer":"Rp30.000,00","code":"MP","errorType":"Model persamaan salah (soal cerita)","wrongAnswers":"Rp25.000","reason":"Menuliskan 2(x + 15.000) + x = 105.000: bagian yang dikali 2 tertukar.","feedback":"Pembeli membeli 2 angklung KECIL dan 1 angklung BESAR. Cek lagi bagian mana yang dikali 2."},{"id":43,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Angklung - Jawa Barat) Harga angklung besar Rp15.000,00 lebih mahal daripada angklung kecil. Pembeli membayar Rp105.000,00 untuk 2 angklung kecil dan 1 angklung besar. Berapakah harga 1 angklung kecil?","correctAnswer":"Rp30.000,00","code":"MP","errorType":"Model persamaan salah (soal cerita)","wrongAnswers":"Rp40.000","reason":"Menambah selisih: (105.000 + 15.000) : 3.","feedback":"Selisih Rp15.000 hanya ada pada angklung besar. Dari total, selisih itu harus disingkirkan dulu (dikurangi), bukan ditambah."},{"id":43,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Angklung - Jawa Barat) Harga angklung besar Rp15.000,00 lebih mahal daripada angklung kecil. Pembeli membayar Rp105.000,00 untuk 2 angklung kecil dan 1 angklung besar. Berapakah harga 1 angklung kecil?","correctAnswer":"Rp30.000,00","code":"LM","errorType":"Langkah belum lengkap","wrongAnswers":"Rp90.000","reason":"Berhenti di 3x = 90.000 (belum dibagi 3).","feedback":"Bagus, persamaanmu sudah benar! Tapi 90.000 itu untuk 3 angklung kecil. Berapa harga 1 angklung kecil?"},{"id":44,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Rumah Gadang - Sumatra Barat) Ukiran dinding berbentuk persegipanjang dengan panjang (2x + 3) cm dan lebar x cm. Jika kelilingnya 54 cm, berapakah nilai x?","correctAnswer":"x = 8","code":"MP","errorType":"Model persamaan salah (soal cerita)","wrongAnswers":"17","reason":"Memakai keliling = p + l (lupa dikali 2).","feedback":"Keliling persegipanjang = 2 x (panjang + lebar). Tulis ulang persamaanmu dengan rumus keliling yang lengkap."},{"id":44,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Rumah Gadang - Sumatra Barat) Ukiran dinding berbentuk persegipanjang dengan panjang (2x + 3) cm dan lebar x cm. Jika kelilingnya 54 cm, berapakah nilai x?","correctAnswer":"x = 8","code":"MP","errorType":"Model persamaan salah (soal cerita)","wrongAnswers":"9,6","reason":"Memakai keliling = 2p + l (angka 2 hanya mengalikan panjang).","feedback":"Pada keliling = 2 x (panjang + lebar), angka 2 mengalikan KEDUANYA. Periksa tanda kurung di persamaanmu."},{"id":44,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Rumah Gadang - Sumatra Barat) Ukiran dinding berbentuk persegipanjang dengan panjang (2x + 3) cm dan lebar x cm. Jika kelilingnya 54 cm, berapakah nilai x?","correctAnswer":"x = 8","code":"DS","errorType":"Distribusi (membuka kurung) keliru","wrongAnswers":"8,5","reason":"Membuka 2(3x + 3) menjadi 6x + 3: angka 3 tidak ikut dikali 2.","feedback":"Angka 2 di depan kurung harus mengalikan kedua suku di dalamnya, termasuk 3."},{"id":44,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Rumah Gadang - Sumatra Barat) Ukiran dinding berbentuk persegipanjang dengan panjang (2x + 3) cm dan lebar x cm. Jika kelilingnya 54 cm, berapakah nilai x?","correctAnswer":"x = 8","code":"LM","errorType":"Langkah belum lengkap","wrongAnswers":"24","reason":"Berhenti di 3x = 24 (belum dibagi 3).","feedback":"Persamaanmu sudah benar dan hampir selesai! Tapi x masih dikali 3. Lanjutkan!"},{"id":45,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Kue Lupis - Jawa) Ibu membeli 5 bungkus kue lupis dan menyerahkan Rp50.000,00. Kembaliannya Rp15.000,00. Berapakah harga 1 bungkus kue lupis?","correctAnswer":"Rp7.000,00","code":"MP","errorType":"Model persamaan salah (soal cerita)","wrongAnswers":"Rp13.000","reason":"Menambah kembalian: (50.000 + 15.000) : 5.","feedback":"Uang Rp50.000 diserahkan, lalu sebagian kembali. Jadi harga 5 bungkus = uang yang diberikan ... kembalian. Tulis ulang persamaanmu."},{"id":45,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Kue Lupis - Jawa) Ibu membeli 5 bungkus kue lupis dan menyerahkan Rp50.000,00. Kembaliannya Rp15.000,00. Berapakah harga 1 bungkus kue lupis?","correctAnswer":"Rp7.000,00","code":"MP","errorType":"Model persamaan salah (soal cerita)","wrongAnswers":"Rp10.000","reason":"Mengabaikan kembalian: 50.000 : 5.","feedback":"Ibu tidak menghabiskan seluruh Rp50.000: ada kembalian Rp15.000. Masukkan kembalian itu ke persamaanmu."},{"id":45,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Kue Lupis - Jawa) Ibu membeli 5 bungkus kue lupis dan menyerahkan Rp50.000,00. Kembaliannya Rp15.000,00. Berapakah harga 1 bungkus kue lupis?","correctAnswer":"Rp7.000,00","code":"MP","errorType":"Model persamaan salah (soal cerita)","wrongAnswers":"Rp3.000","reason":"Hanya memakai kembalian: 15.000 : 5.","feedback":"Rp15.000 itu uang kembalian, bukan harga kue. Harga kue adalah uang yang benar-benar dibayarkan. Berapa itu?"},{"id":45,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Kue Lupis - Jawa) Ibu membeli 5 bungkus kue lupis dan menyerahkan Rp50.000,00. Kembaliannya Rp15.000,00. Berapakah harga 1 bungkus kue lupis?","correctAnswer":"Rp7.000,00","code":"LM","errorType":"Langkah belum lengkap","wrongAnswers":"Rp35.000","reason":"Berhenti di 5x = 35.000 (harga 5 bungkus), lupa membagi 5.","feedback":"Bagus, persamaanmu sudah benar! Tapi 35.000 itu harga 5 bungkus. Yang ditanyakan harga 1 bungkus."},{"id":45,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Kue Lupis - Jawa) Ibu membeli 5 bungkus kue lupis dan menyerahkan Rp50.000,00. Kembaliannya Rp15.000,00. Berapakah harga 1 bungkus kue lupis?","correctAnswer":"Rp7.000,00","code":"HT","errorType":"Kesalahan hitung","wrongAnswers":"Rp6.000 atau Rp8.000","reason":"Langkah benar (35.000 : 5), tetapi hasil bagi salah hitung.","feedback":"Langkahmu sudah tepat! Tinggal teliti hasil pembagian 35.000 : 5."},{"id":46,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Keris - Nusantara) Panjang keris Luk 5 adalah 8 cm lebih panjang daripada keris Luk 3. Total panjang kedua keris berdampingan 72 cm. Berapakah panjang keris Luk 3?","correctAnswer":"32 cm","code":"MP","errorType":"Model persamaan salah (soal cerita)","wrongAnswers":"36","reason":"Membagi total 72 : 2: menganggap kedua keris sama panjang.","feedback":"Keris Luk 5 lebih panjang 8 cm daripada Luk 3. Jika Luk 3 = x, bagaimana menuliskan panjang Luk 5?"},{"id":46,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Keris - Nusantara) Panjang keris Luk 5 adalah 8 cm lebih panjang daripada keris Luk 3. Total panjang kedua keris berdampingan 72 cm. Berapakah panjang keris Luk 3?","correctAnswer":"32 cm","code":"PT","errorType":"Menjawab besaran lain","wrongAnswers":"40","reason":"Menjawab panjang keris Luk 5, atau memodelkan Luk 3 = Luk 5 + 8.","feedback":"Periksa pertanyaannya: yang dicari Luk 3 atau Luk 5? Dan siapa yang lebih panjang?"},{"id":46,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Keris - Nusantara) Panjang keris Luk 5 adalah 8 cm lebih panjang daripada keris Luk 3. Total panjang kedua keris berdampingan 72 cm. Berapakah panjang keris Luk 3?","correctAnswer":"32 cm","code":"LM","errorType":"Langkah belum lengkap","wrongAnswers":"64","reason":"Berhenti di 2x = 64 (belum dibagi 2).","feedback":"Persamaanmu sudah benar dan hampir selesai! Tapi x masih dikali 2. Lanjutkan!"},{"id":46,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Keris - Nusantara) Panjang keris Luk 5 adalah 8 cm lebih panjang daripada keris Luk 3. Total panjang kedua keris berdampingan 72 cm. Berapakah panjang keris Luk 3?","correctAnswer":"32 cm","code":"HT","errorType":"Kesalahan hitung","wrongAnswers":"31 atau 33","reason":"Langkah benar (64 : 2), tetapi hasil bagi salah hitung.","feedback":"Langkahmu sudah tepat! Tinggal teliti hasil pembagian 64 : 2."},{"id":47,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Congklak) Biji Budi 3 kali lipat biji Ani. Jika Budi memberikan 10 biji kepada Ani, jumlah biji mereka sama banyak. Berapakah jumlah biji Ani pada awal permainan?","correctAnswer":"10 biji","code":"PT","errorType":"Menjawab besaran lain","wrongAnswers":"30","reason":"Menjawab banyak biji Budi sebelum memberi (3x).","feedback":"Kamu sudah menemukan x dengan benar! Tapi periksa pertanyaannya: yang ditanyakan biji Ani atau biji Budi?"},{"id":47,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Congklak) Biji Budi 3 kali lipat biji Ani. Jika Budi memberikan 10 biji kepada Ani, jumlah biji mereka sama banyak. Berapakah jumlah biji Ani pada awal permainan?","correctAnswer":"10 biji","code":"MP","errorType":"Model persamaan salah (soal cerita)","wrongAnswers":"5","reason":"Menulis 3x - 10 = x: lupa bahwa Ani menerima 10 biji.","feedback":"Saat Budi memberi 10 biji, biji Ani juga berubah. Bagaimana menuliskan biji Ani setelah menerima 10?"},{"id":47,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Congklak) Biji Budi 3 kali lipat biji Ani. Jika Budi memberikan 10 biji kepada Ani, jumlah biji mereka sama banyak. Berapakah jumlah biji Ani pada awal permainan?","correctAnswer":"10 biji","code":"MP","errorType":"Model persamaan salah (soal cerita)","wrongAnswers":"-10","reason":"Menulis 3x + 10 = x - 10: pemberi dan penerima tertukar.","feedback":"Budi yang MEMBERI 10 biji (berkurang), Ani yang MENERIMA (bertambah). Periksa tanda pada kedua ruas persamaanmu."},{"id":47,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Congklak) Biji Budi 3 kali lipat biji Ani. Jika Budi memberikan 10 biji kepada Ani, jumlah biji mereka sama banyak. Berapakah jumlah biji Ani pada awal permainan?","correctAnswer":"10 biji","code":"LM","errorType":"Langkah belum lengkap","wrongAnswers":"20","reason":"Berhenti di 2x = 20 (belum dibagi 2).","feedback":"Persamaanmu sudah benar dan hampir selesai! Tapi x masih dikali 2. Lanjutkan!"},{"id":48,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Kain Ulos - Sumatra Utara) Dua lembar Ulos (standar dan super) dijual total Rp450.000,00. Harga Ulos super Rp90.000,00 lebih mahal daripada standar. Berapakah harga Ulos standar?","correctAnswer":"Rp180.000,00","code":"PT","errorType":"Menjawab besaran lain","wrongAnswers":"Rp270.000","reason":"Menjawab harga Ulos super, atau memodelkan standar = super + 90.000.","feedback":"Periksa pertanyaannya: yang dicari Ulos standar atau super? Dan mana yang lebih mahal?"},{"id":48,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Kain Ulos - Sumatra Utara) Dua lembar Ulos (standar dan super) dijual total Rp450.000,00. Harga Ulos super Rp90.000,00 lebih mahal daripada standar. Berapakah harga Ulos standar?","correctAnswer":"Rp180.000,00","code":"MP","errorType":"Model persamaan salah (soal cerita)","wrongAnswers":"Rp225.000","reason":"Membagi total 450.000 : 2: menganggap kedua Ulos berharga sama.","feedback":"Ulos super lebih mahal Rp90.000. Jika Ulos standar = x, bagaimana menuliskan harga Ulos super?"},{"id":48,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Kain Ulos - Sumatra Utara) Dua lembar Ulos (standar dan super) dijual total Rp450.000,00. Harga Ulos super Rp90.000,00 lebih mahal daripada standar. Berapakah harga Ulos standar?","correctAnswer":"Rp180.000,00","code":"LM","errorType":"Langkah belum lengkap","wrongAnswers":"Rp360.000","reason":"Berhenti di 2x = 360.000 (belum dibagi 2).","feedback":"Persamaanmu sudah benar dan hampir selesai! Tapi x masih dikali 2. Lanjutkan!"},{"id":48,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Kain Ulos - Sumatra Utara) Dua lembar Ulos (standar dan super) dijual total Rp450.000,00. Harga Ulos super Rp90.000,00 lebih mahal daripada standar. Berapakah harga Ulos standar?","correctAnswer":"Rp180.000,00","code":"HT","errorType":"Kesalahan hitung","wrongAnswers":"Rp170.000 atau Rp190.000","reason":"Langkah benar (360.000 : 2), tetapi hasil bagi salah hitung.","feedback":"Langkahmu sudah tepat! Tinggal teliti hasil pembagian 360.000 : 2."},{"id":49,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Tari Piring - Sumatra Barat) Piring cadangan adalah 1/4 dari jumlah piring utama yang dipegang penari. Jika seluruh piring ada 25 buah, berapakah jumlah piring utama?","correctAnswer":"20 piring","code":"PT","errorType":"Menjawab besaran lain","wrongAnswers":"5","reason":"Menjawab jumlah piring cadangan (x : 4).","feedback":"Kamu sudah menemukan jumlah salah satu jenis piring! Periksa pertanyaannya: piring utama atau piring cadangan?"},{"id":49,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Tari Piring - Sumatra Barat) Piring cadangan adalah 1/4 dari jumlah piring utama yang dipegang penari. Jika seluruh piring ada 25 buah, berapakah jumlah piring utama?","correctAnswer":"20 piring","code":"MP","errorType":"Model persamaan salah (soal cerita)","wrongAnswers":"6,25","reason":"Menghitung 25 : 4: menganggap cadangan = 1/4 dari SELURUH piring.","feedback":"Piring cadangan adalah 1/4 dari piring UTAMA, bukan dari seluruh piring. Jika utama = x, bagaimana menuliskan cadangan?"},{"id":49,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Tari Piring - Sumatra Barat) Piring cadangan adalah 1/4 dari jumlah piring utama yang dipegang penari. Jika seluruh piring ada 25 buah, berapakah jumlah piring utama?","correctAnswer":"20 piring","code":"MP","errorType":"Model persamaan salah (soal cerita)","wrongAnswers":"18,75","reason":"Menghitung utama = 25 - 25/4: cadangan dianggap 1/4 dari seluruh piring.","feedback":"Piring cadangan adalah 1/4 dari piring UTAMA, bukan dari seluruh piring. Jika utama = x, bagaimana menuliskan cadangan?"},{"id":49,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Tari Piring - Sumatra Barat) Piring cadangan adalah 1/4 dari jumlah piring utama yang dipegang penari. Jika seluruh piring ada 25 buah, berapakah jumlah piring utama?","correctAnswer":"20 piring","code":"MP","errorType":"Model persamaan salah (soal cerita)","wrongAnswers":"100","reason":"Menghitung 25 x 4: menganggap 25 adalah jumlah cadangan.","feedback":"25 adalah jumlah SELURUH piring (utama + cadangan). Tulis utama dan cadangan dalam x, lalu jumlahkan sama dengan 25."},{"id":49,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Tari Piring - Sumatra Barat) Piring cadangan adalah 1/4 dari jumlah piring utama yang dipegang penari. Jika seluruh piring ada 25 buah, berapakah jumlah piring utama?","correctAnswer":"20 piring","code":"KV","errorType":"Keliru kali/bagi","wrongAnswers":"31,25","reason":"Mengalikan 25 x 5/4: memakai pecahan yang sama, bukan kebalikannya.","feedback":"Koefisien x adalah 5/4. Supaya x sendirian, kalikan dengan KEBALIKAN dari 5/4."},{"id":49,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Tari Piring - Sumatra Barat) Piring cadangan adalah 1/4 dari jumlah piring utama yang dipegang penari. Jika seluruh piring ada 25 buah, berapakah jumlah piring utama?","correctAnswer":"20 piring","code":"PC","errorType":"Pecahan / desimal","wrongAnswers":"62,5","reason":"Menjumlahkan x + 1/4 x sebagai 2/5 x (pembilang dan penyebut dijumlah terpisah).","feedback":"Hati-hati menjumlahkan: x + 1/4 x bukan 2/5 x. Ubah x menjadi 4/4 x dulu, baru jumlahkan pembilangnya."},{"id":50,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Sekaten - Yogyakarta) Jumlah wajik merah 20 buah lebih sedikit dari dua kali jumlah wajik putih. Jika wajik merah 80 buah, berapakah jumlah wajik putih?","correctAnswer":"50 buah","code":"MP","errorType":"Model persamaan salah (soal cerita)","wrongAnswers":"30","reason":"Mengartikan 'lebih sedikit' sebagai penjumlahan: 2x + 20 = 80.","feedback":"'20 lebih sedikit dari dua kali' artinya dua kali x DIKURANGI 20. Tulis ulang persamaanmu."},{"id":50,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Sekaten - Yogyakarta) Jumlah wajik merah 20 buah lebih sedikit dari dua kali jumlah wajik putih. Jika wajik merah 80 buah, berapakah jumlah wajik putih?","correctAnswer":"50 buah","code":"LM","errorType":"Langkah belum lengkap","wrongAnswers":"100","reason":"Berhenti di 2x = 100 (belum dibagi 2), atau melewatkan 'dua kali' (x - 20 = 80).","feedback":"Periksa persamaanmu: adakah 'dua kali' pada wajik putih? Dan kalau sudah, x masih dikali 2, lanjutkan!"},{"id":50,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Sekaten - Yogyakarta) Jumlah wajik merah 20 buah lebih sedikit dari dua kali jumlah wajik putih. Jika wajik merah 80 buah, berapakah jumlah wajik putih?","correctAnswer":"50 buah","code":"PT","errorType":"Menjawab besaran lain","wrongAnswers":"80","reason":"Menjawab banyak wajik merah (yang sudah diketahui di soal).","feedback":"80 adalah jumlah wajik merah dan itu sudah diketahui. Periksa pertanyaannya: yang dicari wajik putih atau merah?"},{"id":50,"chapter":"Ch 5 - Soal Cerita Etnomatematika","question":"(Sekaten - Yogyakarta) Jumlah wajik merah 20 buah lebih sedikit dari dua kali jumlah wajik putih. Jika wajik merah 80 buah, berapakah jumlah wajik putih?","correctAnswer":"50 buah","code":"HT","errorType":"Kesalahan hitung","wrongAnswers":"40 atau 60","reason":"Langkah benar (2x = 100), tetapi hasil bagi salah hitung.","feedback":"Langkahmu sudah tepat! Tinggal teliti hasil pembagian 100 : 2."}];

export const FEEDBACK_BANK_EN = [{"id":1,"chapter":"Ch 1 - Addition & Subtraction","question":"x + 7 = 15","correctAnswer":"x = 8","code":"OP","errorType":"Wrong inverse operation","wrongAnswers":"22","reason":"Adds 15 + 7: uses the same operation instead of the opposite one.","feedback":"Almost! On the left side, 7 is being added to x. Which operation can 'cancel out' adding 7 so that x is alone? Do the same on the right side too."},{"id":1,"chapter":"Ch 1 - Addition & Subtraction","question":"x + 7 = 15","correctAnswer":"x = 8","code":"HT","errorType":"Calculation error","wrongAnswers":"7 or 9","reason":"The steps are correct (15 - 7), but the subtraction result is miscalculated.","feedback":"Your steps are right! Just double-check the subtraction result. Try calculating it again slowly."},{"id":1,"chapter":"Ch 1 - Addition & Subtraction","question":"x + 7 = 15","correctAnswer":"x = 8","code":"LM","errorType":"Incomplete steps","wrongAnswers":"15","reason":"Assumes the number on the right side is directly the value of x, without removing + 7.","feedback":"Test your answer: if x = 15, does x + 7 really equal 15? There is still a number you haven't removed from x."},{"id":2,"chapter":"Ch 1 - Addition & Subtraction","question":"y - 9 = 4","correctAnswer":"y = 13","code":"OP","errorType":"Wrong inverse operation","wrongAnswers":"-5","reason":"Computes 4 - 9: repeats the same operation (- 9) instead of its opposite.","feedback":"On the left side, 9 is subtracted from y. To get y alone, that 9 must be 'given back'. Which operation does that? Do the same on the right side."},{"id":2,"chapter":"Ch 1 - Addition & Subtraction","question":"y - 9 = 4","correctAnswer":"y = 13","code":"TD","errorType":"Sign / order error","wrongAnswers":"5","reason":"Subtracts the smaller number from the larger one (9 - 4), ignoring which number is the starting point.","feedback":"Watch the order. On the right side there is 4, and 9 'moves' there using the opposite operation. Rewrite your step starting from 4."},{"id":2,"chapter":"Ch 1 - Addition & Subtraction","question":"y - 9 = 4","correctAnswer":"y = 13","code":"HT","errorType":"Calculation error","wrongAnswers":"12 or 14","reason":"The steps are correct (4 + 9), but the addition result is miscalculated.","feedback":"Your steps are right! Just double-check the addition result. Try calculating it again."},{"id":3,"chapter":"Ch 1 - Addition & Subtraction","question":"a + 12 = 5","correctAnswer":"a = -7","code":"TD","errorType":"Sign / order error","wrongAnswers":"7","reason":"Computes 12 - 5 (subtracting the smaller number from the larger one), so the negative sign is lost.","feedback":"You subtracted correctly! Now check the sign: is 5 minus 12 positive or negative? Picture the number line."},{"id":3,"chapter":"Ch 1 - Addition & Subtraction","question":"a + 12 = 5","correctAnswer":"a = -7","code":"OP","errorType":"Wrong inverse operation","wrongAnswers":"17","reason":"Adds 5 + 12: repeats the same operation.","feedback":"On the left side, 12 is added to a. If you add again on the right, the 12 will never disappear from a. Which operation is the opposite of adding?"},{"id":3,"chapter":"Ch 1 - Addition & Subtraction","question":"a + 12 = 5","correctAnswer":"a = -7","code":"HT","errorType":"Calculation error","wrongAnswers":"-6 or -8","reason":"The steps are correct (5 - 12), but the result is miscalculated.","feedback":"Your steps are right! Recalculate: starting at 5, move back 12 steps on the number line. Where do you stop?"},{"id":4,"chapter":"Ch 1 - Addition & Subtraction","question":"m - 15 = -8","correctAnswer":"m = 7","code":"OP","errorType":"Wrong inverse operation","wrongAnswers":"-23","reason":"Computes -8 - 15: repeats the same operation.","feedback":"On the left side, 15 is subtracted from m. To get m alone, which operation must you do on both sides?"},{"id":4,"chapter":"Ch 1 - Addition & Subtraction","question":"m - 15 = -8","correctAnswer":"m = 7","code":"TD","errorType":"Sign / order error","wrongAnswers":"-7","reason":"Adds 15 correctly, but computes -8 + 15 as -(15 - 8): gets thrown off by the negative sign.","feedback":"You added 15, great! Now check -8 + 15: start at -8 and move forward 15 steps. Do you stop at a positive or a negative number?"},{"id":4,"chapter":"Ch 1 - Addition & Subtraction","question":"m - 15 = -8","correctAnswer":"m = 7","code":"TD","errorType":"Sign / order error","wrongAnswers":"23","reason":"Ignores the negative sign on -8 (computes 8 + 15).","feedback":"Don't forget the sign on the right side: the number is -8, not 8. Rewrite your step with the negative sign."},{"id":5,"chapter":"Ch 1 - Addition & Subtraction","question":"18 + x = 30","correctAnswer":"x = 12","code":"OP","errorType":"Wrong inverse operation","wrongAnswers":"48","reason":"Adds 30 + 18: repeats the same operation.","feedback":"On the left side, 18 is added to x. Which operation can remove 18? Do it on both sides."},{"id":5,"chapter":"Ch 1 - Addition & Subtraction","question":"18 + x = 30","correctAnswer":"x = 12","code":"TD","errorType":"Sign / order error","wrongAnswers":"-12","reason":"Reverses the order of subtraction (18 - 30).","feedback":"Almost! Check the order of subtraction: the number you are removing is 18, so it should be 30 minus what?"},{"id":5,"chapter":"Ch 1 - Addition & Subtraction","question":"18 + x = 30","correctAnswer":"x = 12","code":"HT","errorType":"Calculation error","wrongAnswers":"11 or 13","reason":"The steps are correct (30 - 18), but the result is miscalculated.","feedback":"Your steps are right! Just double-check the result of 30 - 18."},{"id":6,"chapter":"Ch 1 - Addition & Subtraction","question":"p - 6,5 = 3,5","correctAnswer":"p = 10","code":"OP","errorType":"Wrong inverse operation","wrongAnswers":"-3","reason":"Computes 3.5 - 6.5: repeats the same operation.","feedback":"On the left side, 6.5 is subtracted from p. To get p alone, which operation must you do on both sides?"},{"id":6,"chapter":"Ch 1 - Addition & Subtraction","question":"p - 6,5 = 3,5","correctAnswer":"p = 10","code":"PC","errorType":"Fraction / decimal error","wrongAnswers":"9 or 9.1","reason":"The steps are correct (3.5 + 6.5), but adds the decimals incorrectly: the 0.5 + 0.5 is not 'carried' into the whole number, or the result is written as 9.10.","feedback":"Your steps are right! Double-check the decimal addition: what is 0.5 + 0.5, and where does the 'carry' go?"},{"id":7,"chapter":"Ch 1 - Addition & Subtraction","question":"k + 1/2 = 3","correctAnswer":"k = 5/2 or 2.5","code":"OP","errorType":"Wrong inverse operation","wrongAnswers":"3.5","reason":"Adds 3 + 1/2: repeats the same operation.","feedback":"On the left side, 1/2 is added to k. Which operation is the opposite of adding? Do it on both sides."},{"id":7,"chapter":"Ch 1 - Addition & Subtraction","question":"k + 1/2 = 3","correctAnswer":"k = 5/2 or 2.5","code":"PC","errorType":"Fraction / decimal error","wrongAnswers":"1","reason":"Computes 3 - 1/2 as (3 - 1)/2 = 1.","feedback":"Your subtraction step is right! But 3 - 1/2 can't be calculated like that. Turn 3 into a fraction with denominator 2 first, then subtract."},{"id":7,"chapter":"Ch 1 - Addition & Subtraction","question":"k + 1/2 = 3","correctAnswer":"k = 5/2 or 2.5","code":"PC","errorType":"Fraction / decimal error","wrongAnswers":"2","reason":"Ignores the fraction 1/2 when moving it to the other side (3 - 1).","feedback":"The fraction 1/2 has to be moved too, and its value still has to be calculated. What is 3 - 1/2? Write it as a mixed number first if you need to."},{"id":8,"chapter":"Ch 1 - Addition & Subtraction","question":"-7 + n = 14","correctAnswer":"n = 21","code":"OP","errorType":"Wrong inverse operation","wrongAnswers":"7","reason":"Computes 14 - 7: moves -7 without flipping the operation.","feedback":"The -7 on the left side means n has 7 taken away. To make the -7 disappear, which operation must you do on both sides?"},{"id":8,"chapter":"Ch 1 - Addition & Subtraction","question":"-7 + n = 14","correctAnswer":"n = 21","code":"TD","errorType":"Sign / order error","wrongAnswers":"-21","reason":"Adds 14 + 7 correctly, but puts a negative sign on the result.","feedback":"The addition is right! Now check the sign: test your answer. Does -7 + (your answer) really equal 14?"},{"id":8,"chapter":"Ch 1 - Addition & Subtraction","question":"-7 + n = 14","correctAnswer":"n = 21","code":"HT","errorType":"Calculation error","wrongAnswers":"20 or 22","reason":"The steps are correct (14 + 7), but the result is miscalculated.","feedback":"Your steps are right! Just double-check 14 + 7."},{"id":9,"chapter":"Ch 1 - Addition & Subtraction","question":"x - 14 = -20","correctAnswer":"x = -6","code":"OP","errorType":"Wrong inverse operation","wrongAnswers":"-34","reason":"Computes -20 - 14: repeats the same operation.","feedback":"On the left side, 14 is subtracted from x. Which operation can 'give back' the 14? Do it on both sides."},{"id":9,"chapter":"Ch 1 - Addition & Subtraction","question":"x - 14 = -20","correctAnswer":"x = -6","code":"TD","errorType":"Sign / order error","wrongAnswers":"6","reason":"Computes -20 + 14 but writes the result as positive: the negative sign is lost.","feedback":"You added 14 correctly! Check the sign of the result: start at -20 and move forward 14 steps. Do you stop at a positive or a negative number?"},{"id":9,"chapter":"Ch 1 - Addition & Subtraction","question":"x - 14 = -20","correctAnswer":"x = -6","code":"TD","errorType":"Sign / order error","wrongAnswers":"34","reason":"Ignores the negative sign on -20 (computes 20 + 14).","feedback":"The negative sign on -20 must not disappear. Rewrite your right side with the correct sign."},{"id":9,"chapter":"Ch 1 - Addition & Subtraction","question":"x - 14 = -20","correctAnswer":"x = -6","code":"HT","errorType":"Calculation error","wrongAnswers":"-5 or -7","reason":"The steps are correct (-20 + 14), but the result is miscalculated.","feedback":"Your steps are right! Recalculate -20 + 14 on the number line."},{"id":10,"chapter":"Ch 1 - Addition & Subtraction","question":"y + 25 = 11","correctAnswer":"y = -14","code":"TD","errorType":"Sign / order error","wrongAnswers":"14","reason":"Computes 25 - 11 (reversed order), so the negative sign is lost.","feedback":"You subtracted 25, good! But the order is 11 minus 25, not the other way around. Is the result positive or negative?"},{"id":10,"chapter":"Ch 1 - Addition & Subtraction","question":"y + 25 = 11","correctAnswer":"y = -14","code":"OP","errorType":"Wrong inverse operation","wrongAnswers":"36","reason":"Adds 11 + 25: repeats the same operation.","feedback":"On the left side, 25 is added to y. Which operation is the opposite of adding? Do it on both sides."},{"id":10,"chapter":"Ch 1 - Addition & Subtraction","question":"y + 25 = 11","correctAnswer":"y = -14","code":"HT","errorType":"Calculation error","wrongAnswers":"-13 or -15","reason":"The steps are correct (11 - 25), but the result is miscalculated.","feedback":"Your steps are right! Recalculate 11 - 25: from 11, move back 25 steps."},{"id":11,"chapter":"Ch 2 - Multiplication & Division","question":"4x = 28","correctAnswer":"x = 7","code":"KV","errorType":"Multiply/divide confusion","wrongAnswers":"112","reason":"Multiplies 28 x 4: thinks that removing the 4 means multiplying.","feedback":"4x means 4 times x. To get x alone, which operation is the opposite of 'multiplied by 4'?"},{"id":11,"chapter":"Ch 2 - Multiplication & Division","question":"4x = 28","correctAnswer":"x = 7","code":"KV","errorType":"Multiply/divide confusion","wrongAnswers":"1/7 (≈ 0.14)","reason":"Divides 4 by 28: the order of division is reversed.","feedback":"You chose division, good! But the order is swapped: you divide the number on the right side, and the divisor is the coefficient of x."},{"id":11,"chapter":"Ch 2 - Multiplication & Division","question":"4x = 28","correctAnswer":"x = 7","code":"OP","errorType":"Wrong inverse operation","wrongAnswers":"24","reason":"Treats 4x as 4 + x, then subtracts 4 from 28.","feedback":"4x is not 4 + x, it is 4 times x. Test your answer: does 4 times your answer equal 28?"},{"id":11,"chapter":"Ch 2 - Multiplication & Division","question":"4x = 28","correctAnswer":"x = 7","code":"HT","errorType":"Calculation error","wrongAnswers":"6 or 8","reason":"The steps are correct (28 : 4), but the division result is miscalculated.","feedback":"Your steps are right! Just double-check the result of 28 : 4."},{"id":12,"chapter":"Ch 2 - Multiplication & Division","question":"-3y = 21","correctAnswer":"y = -7","code":"TD","errorType":"Sign / order error","wrongAnswers":"7","reason":"Divides 21 : 3 and ignores the negative sign on -3.","feedback":"Nice, you divided! But divide by -3 (not 3). When a positive number is divided by a negative number, is the result positive or negative?"},{"id":12,"chapter":"Ch 2 - Multiplication & Division","question":"-3y = 21","correctAnswer":"y = -7","code":"KV","errorType":"Multiply/divide confusion","wrongAnswers":"-63","reason":"Multiplies 21 x (-3): thinks that removing -3 means multiplying.","feedback":"-3y means -3 times y. To get y alone, which operation is the opposite of multiplying?"},{"id":12,"chapter":"Ch 2 - Multiplication & Division","question":"-3y = 21","correctAnswer":"y = -7","code":"OP","errorType":"Wrong inverse operation","wrongAnswers":"24 or 18","reason":"Treats -3y as -3 + y, then adds/subtracts 3 from 21.","feedback":"-3y is not -3 + y, it is -3 times y. The opposite operation of 'multiply' is ...?"},{"id":12,"chapter":"Ch 2 - Multiplication & Division","question":"-3y = 21","correctAnswer":"y = -7","code":"HT","errorType":"Calculation error","wrongAnswers":"-6 or -8","reason":"The steps are correct (21 : -3), but the division result is miscalculated.","feedback":"Your steps are right! Just double-check the division result."},{"id":13,"chapter":"Ch 2 - Multiplication & Division","question":"a/5 = 6","correctAnswer":"a = 30","code":"KV","errorType":"Multiply/divide confusion","wrongAnswers":"1.2","reason":"Divides 6 : 5: thinks that removing '÷ 5' means dividing again.","feedback":"In the problem, a is being divided by 5. To get a alone, the opposite operation of 'divided by 5' is ...? Do it on both sides."},{"id":13,"chapter":"Ch 2 - Multiplication & Division","question":"a/5 = 6","correctAnswer":"a = 30","code":"OP","errorType":"Wrong inverse operation","wrongAnswers":"1 or 11","reason":"Treats a/5 as a - 5 (or a + 5), then adds/subtracts 5 from 6.","feedback":"a/5 does not mean a minus 5. It means a divided by 5. What is the opposite of 'divide'?"},{"id":13,"chapter":"Ch 2 - Multiplication & Division","question":"a/5 = 6","correctAnswer":"a = 30","code":"HT","errorType":"Calculation error","wrongAnswers":"25 or 35","reason":"The steps are correct (6 x 5), but the multiplication result is miscalculated.","feedback":"Your steps are right! Just double-check the result of 6 x 5."},{"id":14,"chapter":"Ch 2 - Multiplication & Division","question":"m/4 = -9","correctAnswer":"m = -36","code":"TD","errorType":"Sign / order error","wrongAnswers":"36","reason":"Multiplies -9 x 4 but writes the result as positive: the negative sign is lost.","feedback":"You multiplied by 4, good! Check the sign: is -9 times 4 positive or negative?"},{"id":14,"chapter":"Ch 2 - Multiplication & Division","question":"m/4 = -9","correctAnswer":"m = -36","code":"KV","errorType":"Multiply/divide confusion","wrongAnswers":"-2.25","reason":"Divides -9 : 4: thinks that removing '/4' means dividing again.","feedback":"m is being divided by 4. To get m alone, the opposite operation of 'divided by 4' is ...?"},{"id":14,"chapter":"Ch 2 - Multiplication & Division","question":"m/4 = -9","correctAnswer":"m = -36","code":"OP","errorType":"Wrong inverse operation","wrongAnswers":"-5 or -13","reason":"Treats m/4 as m - 4, then adds/subtracts 4 from -9.","feedback":"m/4 does not mean m minus 4. It means m divided by 4. What is the opposite of 'divide'?"},{"id":15,"chapter":"Ch 2 - Multiplication & Division","question":"(2/3)x = 12","correctAnswer":"x = 18","code":"KV","errorType":"Multiply/divide confusion","wrongAnswers":"8","reason":"Multiplies 12 x 2/3: uses the same fraction instead of its reciprocal.","feedback":"The coefficient of x is 2/3. To get x alone, multiply by the RECIPROCAL of 2/3, the fraction with the numerator and denominator swapped."},{"id":15,"chapter":"Ch 2 - Multiplication & Division","question":"(2/3)x = 12","correctAnswer":"x = 18","code":"LM","errorType":"Incomplete steps","wrongAnswers":"6","reason":"Only divides 12 by 2 (the numerator) and stops, forgetting to multiply by 3.","feedback":"You have only dealt with the 2 so far. There is still the 3 as the denominator. Use the reciprocal of 2/3 all at once."},{"id":15,"chapter":"Ch 2 - Multiplication & Division","question":"(2/3)x = 12","correctAnswer":"x = 18","code":"LM","errorType":"Incomplete steps","wrongAnswers":"36","reason":"Only multiplies 12 by 3 (the denominator), forgetting to divide by 2.","feedback":"You have only dealt with the 3 so far. There is still the 2 as the numerator. Use the reciprocal of 2/3 all at once."},{"id":16,"chapter":"Ch 2 - Multiplication & Division","question":"-8p = -56","correctAnswer":"p = 7","code":"TD","errorType":"Sign / order error","wrongAnswers":"-7","reason":"Divides -56 : 8, ignoring the negative sign on the divisor (-8).","feedback":"Nice, you divided! Check the sign: when a negative number is divided by a negative number, is the result positive or negative?"},{"id":16,"chapter":"Ch 2 - Multiplication & Division","question":"-8p = -56","correctAnswer":"p = 7","code":"KV","errorType":"Multiply/divide confusion","wrongAnswers":"448","reason":"Multiplies -56 x (-8): thinks that removing -8 means multiplying.","feedback":"-8p means -8 times p. To get p alone, which operation is the opposite of multiplying?"},{"id":16,"chapter":"Ch 2 - Multiplication & Division","question":"-8p = -56","correctAnswer":"p = 7","code":"OP","errorType":"Wrong inverse operation","wrongAnswers":"-64 or -48","reason":"Treats -8p as -8 + p, then adds/subtracts 8 from -56.","feedback":"-8p is not -8 + p, it is -8 times p. The opposite operation of 'multiply' is ...?"},{"id":16,"chapter":"Ch 2 - Multiplication & Division","question":"-8p = -56","correctAnswer":"p = 7","code":"HT","errorType":"Calculation error","wrongAnswers":"6 or 8","reason":"The steps are correct (-56 : -8), but the division result is miscalculated.","feedback":"Your steps are right! Just double-check the result of 56 : 8."},{"id":17,"chapter":"Ch 2 - Multiplication & Division","question":"y/0,5 = 14","correctAnswer":"y = 7","code":"KV","errorType":"Multiply/divide confusion","wrongAnswers":"28","reason":"Divides 14 : 0.5: thinks that removing '/0.5' means dividing again.","feedback":"y is already divided by 0.5. To get y alone, the opposite of 'divide' is ...?"},{"id":17,"chapter":"Ch 2 - Multiplication & Division","question":"y/0,5 = 14","correctAnswer":"y = 7","code":"PC","errorType":"Fraction / decimal error","wrongAnswers":"70 or 0.7","reason":"Multiplies 14 x 0.5 but misplaces the decimal point in the result.","feedback":"You multiplied, which is the right step! Check the decimal point: does it make sense for 14 times a number less than 1 to give a result that big?"},{"id":17,"chapter":"Ch 2 - Multiplication & Division","question":"y/0,5 = 14","correctAnswer":"y = 7","code":"OP","errorType":"Wrong inverse operation","wrongAnswers":"13.5 or 14.5","reason":"Treats y/0.5 as y - 0.5, then adds/subtracts 0.5 from 14.","feedback":"y/0.5 means y DIVIDED by 0.5, not minus 0.5. What is the opposite operation?"},{"id":18,"chapter":"Ch 2 - Multiplication & Division","question":"0,4k = 1,6","correctAnswer":"k = 4","code":"KV","errorType":"Multiply/divide confusion","wrongAnswers":"0.64","reason":"Multiplies 1.6 x 0.4: thinks that removing 0.4 means multiplying.","feedback":"0.4k means 0.4 times k. To get k alone, which operation is the opposite of multiplying?"},{"id":18,"chapter":"Ch 2 - Multiplication & Division","question":"0,4k = 1,6","correctAnswer":"k = 4","code":"PC","errorType":"Fraction / decimal error","wrongAnswers":"0.4 or 40","reason":"Divides 1.6 : 0.4 but misplaces the decimal point in the result.","feedback":"Your division is right, now check the decimal point. Trick: multiply 1.6 and 0.4 by 10 so they become whole numbers, then divide."},{"id":18,"chapter":"Ch 2 - Multiplication & Division","question":"0,4k = 1,6","correctAnswer":"k = 4","code":"KV","errorType":"Multiply/divide confusion","wrongAnswers":"0.25","reason":"Divides 0.4 : 1.6: the order of division is reversed.","feedback":"You chose division, good! But the order is swapped: you divide 1.6 (the right side), and the divisor is 0.4."},{"id":18,"chapter":"Ch 2 - Multiplication & Division","question":"0,4k = 1,6","correctAnswer":"k = 4","code":"OP","errorType":"Wrong inverse operation","wrongAnswers":"1.2 or 2","reason":"Treats 0.4k as 0.4 + k, then adds/subtracts 0.4 from 1.6.","feedback":"0.4k is not 0.4 + k, it is 0.4 times k. The opposite operation of 'multiply' is ...?"},{"id":19,"chapter":"Ch 2 - Multiplication & Division","question":"-(3/4)n = 15","correctAnswer":"n = -20","code":"TD","errorType":"Sign / order error","wrongAnswers":"20","reason":"Divides 15 by 3/4 and ignores the negative sign on the coefficient -3/4 (the result is written as positive).","feedback":"Your steps are good! Check the sign in the last step: the coefficient is -3/4, so a positive number times a negative reciprocal gives a positive or a negative result?"},{"id":19,"chapter":"Ch 2 - Multiplication & Division","question":"-(3/4)n = 15","correctAnswer":"n = -20","code":"KV","errorType":"Multiply/divide confusion","wrongAnswers":"-11.25 or 11.25","reason":"Multiplies 15 x (-3/4) or 15 x 3/4: uses the same fraction instead of its reciprocal.","feedback":"The coefficient of n is -3/4. To get n alone, multiply by the RECIPROCAL of -3/4, the fraction with the numerator and denominator swapped (the negative sign stays)."},{"id":19,"chapter":"Ch 2 - Multiplication & Division","question":"-(3/4)n = 15","correctAnswer":"n = -20","code":"LM","errorType":"Incomplete steps","wrongAnswers":"-5","reason":"Only divides 15 by -3 (the numerator) and stops, forgetting to multiply by 4.","feedback":"You have only dealt with the 3 so far. There is still the 4 as the denominator. Use the reciprocal of -3/4 all at once."},{"id":19,"chapter":"Ch 2 - Multiplication & Division","question":"-(3/4)n = 15","correctAnswer":"n = -20","code":"LM","errorType":"Incomplete steps","wrongAnswers":"60","reason":"Only multiplies 15 by 4 (the denominator), forgetting to divide by -3.","feedback":"You have only dealt with the 4 so far. There is still the -3 as the numerator. Use the reciprocal of -3/4 all at once."},{"id":20,"chapter":"Ch 2 - Multiplication & Division","question":"15z = -75","correctAnswer":"z = -5","code":"TD","errorType":"Sign / order error","wrongAnswers":"5","reason":"Divides -75 : 15 but writes the result as positive: the negative sign is lost.","feedback":"You divided 75 by 15, good! Check the sign: when a negative number is divided by a positive number, is the result positive or negative?"},{"id":20,"chapter":"Ch 2 - Multiplication & Division","question":"15z = -75","correctAnswer":"z = -5","code":"KV","errorType":"Multiply/divide confusion","wrongAnswers":"-1125","reason":"Multiplies -75 x 15: thinks that removing 15 means multiplying.","feedback":"15z means 15 times z. To get z alone, which operation is the opposite of multiplying?"},{"id":20,"chapter":"Ch 2 - Multiplication & Division","question":"15z = -75","correctAnswer":"z = -5","code":"KV","errorType":"Multiply/divide confusion","wrongAnswers":"-0.2","reason":"Divides 15 : (-75): the order of division is reversed.","feedback":"You chose division, good! But the order is swapped: you divide -75 (the right side), and the divisor is 15."},{"id":20,"chapter":"Ch 2 - Multiplication & Division","question":"15z = -75","correctAnswer":"z = -5","code":"HT","errorType":"Calculation error","wrongAnswers":"-4 or -6","reason":"The steps are correct (-75 : 15), but the division result is miscalculated.","feedback":"Your steps are right! Just double-check the result of 75 : 15."},{"id":21,"chapter":"Ch 3 - Mixed Operations","question":"2x + 5 = 17","correctAnswer":"x = 6","code":"LM","errorType":"Incomplete steps","wrongAnswers":"12","reason":"Stops at 2x = 12 (not yet divided by 2).","feedback":"You removed + 5, good! But x isn't alone yet: there is still a 2 multiplying x. Keep going!"},{"id":21,"chapter":"Ch 3 - Mixed Operations","question":"2x + 5 = 17","correctAnswer":"x = 6","code":"OP","errorType":"Wrong inverse operation","wrongAnswers":"11","reason":"Adds 5 to the right side (17 + 5) and then divides by 2.","feedback":"On the left side, 5 is added to 2x. The opposite of 'add 5' is ...? Do it on both sides before dividing by 2."},{"id":21,"chapter":"Ch 3 - Mixed Operations","question":"2x + 5 = 17","correctAnswer":"x = 6","code":"BS","errorType":"Operation applied to only some terms","wrongAnswers":"3.5 or 14.5","reason":"Divides only one term (17 : 2 - 5, or 17 - 5 : 2).","feedback":"When you divide by 2, ALL terms are divided. Safer approach: remove + 5 from both sides first, then divide by 2."},{"id":21,"chapter":"Ch 3 - Mixed Operations","question":"2x + 5 = 17","correctAnswer":"x = 6","code":"HT","errorType":"Calculation error","wrongAnswers":"5 or 7","reason":"The steps are correct (12 : 2), but the division result is miscalculated.","feedback":"Your steps are right! Just double-check the result of 12 : 2."},{"id":22,"chapter":"Ch 3 - Mixed Operations","question":"3y - 8 = 13","correctAnswer":"y = 7","code":"LM","errorType":"Incomplete steps","wrongAnswers":"21","reason":"Stops at 3y = 21 (not yet divided by 3).","feedback":"You removed - 8, good! But y isn't alone yet: there is still a 3 multiplying y. Keep going!"},{"id":22,"chapter":"Ch 3 - Mixed Operations","question":"3y - 8 = 13","correctAnswer":"y = 7","code":"OP","errorType":"Wrong inverse operation","wrongAnswers":"5/3 (≈ 1.67)","reason":"Subtracts 8 from 13 (repeats the same operation) and then divides by 3.","feedback":"On the left side, 8 is being subtracted. The opposite of 'subtract 8' is ...? Do it on both sides."},{"id":22,"chapter":"Ch 3 - Mixed Operations","question":"3y - 8 = 13","correctAnswer":"y = 7","code":"BS","errorType":"Operation applied to only some terms","wrongAnswers":"37/3 (≈ 12.33)","reason":"Divides 13 : 3 and then adds 8 (divides only one term).","feedback":"When you divide by 3, ALL terms are divided. Safer approach: remove - 8 from both sides first, then divide by 3."},{"id":22,"chapter":"Ch 3 - Mixed Operations","question":"3y - 8 = 13","correctAnswer":"y = 7","code":"HT","errorType":"Calculation error","wrongAnswers":"6 or 8","reason":"The steps are correct (21 : 3), but the division result is miscalculated.","feedback":"Your steps are right! Just double-check the result of 21 : 3."},{"id":23,"chapter":"Ch 3 - Mixed Operations","question":"5a + 12 = -3","correctAnswer":"a = -3","code":"LM","errorType":"Incomplete steps","wrongAnswers":"-15","reason":"Stops at 5a = -15 (not yet divided by 5).","feedback":"You removed + 12, good! But a is still multiplied by 5. Keep going until a is alone."},{"id":23,"chapter":"Ch 3 - Mixed Operations","question":"5a + 12 = -3","correctAnswer":"a = -3","code":"TD","errorType":"Sign / order error","wrongAnswers":"3","reason":"Divides -15 : 5 but writes the result as positive: the negative sign is lost.","feedback":"Your steps are good! Check the sign in the last step: when a negative number is divided by a positive number, is the result positive or negative?"},{"id":23,"chapter":"Ch 3 - Mixed Operations","question":"5a + 12 = -3","correctAnswer":"a = -3","code":"OP","errorType":"Wrong inverse operation","wrongAnswers":"1.8","reason":"Adds 12 to the right side (-3 + 12) and then divides by 5.","feedback":"On the left side, 12 is added to 5a. If you add again, the 12 will never disappear. What is the opposite operation of 'add'?"},{"id":23,"chapter":"Ch 3 - Mixed Operations","question":"5a + 12 = -3","correctAnswer":"a = -3","code":"BS","errorType":"Operation applied to only some terms","wrongAnswers":"-12.6","reason":"Divides -3 : 5 and then subtracts 12 (divides only one term).","feedback":"When you divide by 5, ALL terms are divided. Safer approach: remove + 12 from both sides first, then divide by 5."},{"id":24,"chapter":"Ch 3 - Mixed Operations","question":"4(m - 2) = 16","correctAnswer":"m = 6","code":"DS","errorType":"Distribution (expanding brackets) error","wrongAnswers":"4.5","reason":"Expands 4(m - 2) as 4m - 2: the 2 is not multiplied by 4.","feedback":"Remember: the number in front of the brackets multiplies EVERYTHING inside. Try multiplying 4 by m, then 4 by 2."},{"id":24,"chapter":"Ch 3 - Mixed Operations","question":"4(m - 2) = 16","correctAnswer":"m = 6","code":"DS","errorType":"Distribution (expanding brackets) error","wrongAnswers":"2","reason":"Expands 4(m - 2) as 4m + 8: the negative sign is lost when multiplying.","feedback":"Check the sign when expanding the brackets: is 4 x (-2) positive or negative?"},{"id":24,"chapter":"Ch 3 - Mixed Operations","question":"4(m - 2) = 16","correctAnswer":"m = 6","code":"LM","errorType":"Incomplete steps","wrongAnswers":"4","reason":"Stops at m - 2 = 4 (not yet adding 2).","feedback":"You divided 16 by 4 correctly! But m still has - 2 with it. Keep going until m is alone."},{"id":24,"chapter":"Ch 3 - Mixed Operations","question":"4(m - 2) = 16","correctAnswer":"m = 6","code":"KV","errorType":"Multiply/divide confusion","wrongAnswers":"66","reason":"Multiplies 16 x 4 (instead of dividing) and then adds 2.","feedback":"The 4 in front of the brackets multiplies what is inside. To make that 4 disappear, which operation is the opposite of multiplying?"},{"id":25,"chapter":"Ch 3 - Mixed Operations","question":"(x + 4)/3 = 5","correctAnswer":"x = 11","code":"LM","errorType":"Incomplete steps","wrongAnswers":"15","reason":"Stops at x + 4 = 15 (not yet subtracting 4).","feedback":"You removed the denominator 3, good! But x still has + 4 with it. Keep going!"},{"id":25,"chapter":"Ch 3 - Mixed Operations","question":"(x + 4)/3 = 5","correctAnswer":"x = 11","code":"BS","errorType":"Operation applied to only some terms","wrongAnswers":"11/3 (≈ 3.67)","reason":"Thinks that only the 4 is divided by 3: x + 4/3 = 5.","feedback":"Look at the fraction bar: (x + 4) is ENTIRELY divided by 3, not just the 4. When you multiply the left side by 3, what happens to the top part?"},{"id":25,"chapter":"Ch 3 - Mixed Operations","question":"(x + 4)/3 = 5","correctAnswer":"x = 11","code":"OP","errorType":"Wrong inverse operation","wrongAnswers":"19","reason":"Multiplies 5 x 3 and then adds 4 (it should be subtracted).","feedback":"On the left side, 4 is added to x. The opposite of 'add 4' is ...? Do it on both sides."},{"id":25,"chapter":"Ch 3 - Mixed Operations","question":"(x + 4)/3 = 5","correctAnswer":"x = 11","code":"HT","errorType":"Calculation error","wrongAnswers":"10 or 12","reason":"The steps are correct (15 - 4), but the result is miscalculated.","feedback":"Your steps are right! Just double-check the result of 15 - 4."},{"id":26,"chapter":"Ch 3 - Mixed Operations","question":"-2p + 9 = 25","correctAnswer":"p = -8","code":"TD","errorType":"Sign / order error","wrongAnswers":"8","reason":"Divides 16 : 2, ignoring the negative sign on the coefficient -2.","feedback":"Almost! You divided 16 by 2. But the coefficient is -2, not 2. A positive number divided by a negative number gives ...?"},{"id":26,"chapter":"Ch 3 - Mixed Operations","question":"-2p + 9 = 25","correctAnswer":"p = -8","code":"OP","errorType":"Wrong inverse operation","wrongAnswers":"-17","reason":"Adds 9 to the right side (25 + 9) and then divides by -2.","feedback":"On the left side, 9 is added to -2p. The opposite of 'add 9' is ...? Do it on both sides."},{"id":26,"chapter":"Ch 3 - Mixed Operations","question":"-2p + 9 = 25","correctAnswer":"p = -8","code":"LM","errorType":"Incomplete steps","wrongAnswers":"16","reason":"Stops at -2p = 16 (not yet divided by -2).","feedback":"Good, you removed + 9! But p is still multiplied by -2. Keep going until p is alone."},{"id":26,"chapter":"Ch 3 - Mixed Operations","question":"-2p + 9 = 25","correctAnswer":"p = -8","code":"KV","errorType":"Multiply/divide confusion","wrongAnswers":"-32","reason":"Multiplies 16 x (-2): thinks that removing -2 means multiplying.","feedback":"-2p means -2 times p. To get p alone, which operation is the opposite of multiplying?"},{"id":27,"chapter":"Ch 3 - Mixed Operations","question":"7 - 3k = -11","correctAnswer":"k = 6","code":"TD","errorType":"Sign / order error","wrongAnswers":"-6","reason":"Divides -18 : (-3) but writes the result as negative.","feedback":"Your steps are good! Check the sign in the last step: is a negative number divided by a negative number positive or negative?"},{"id":27,"chapter":"Ch 3 - Mixed Operations","question":"7 - 3k = -11","correctAnswer":"k = 6","code":"PR","errorType":"Transposition error","wrongAnswers":"4/3 (≈ 1.33)","reason":"Removes 7 using -11 + 7: the sign of 7 doesn't change when it moves to the other side.","feedback":"When 7 moves to the right side, its sign changes. + 7 on the left becomes ... on the right. Try the first step again."},{"id":27,"chapter":"Ch 3 - Mixed Operations","question":"7 - 3k = -11","correctAnswer":"k = 6","code":"GS","errorType":"Combining unlike terms","wrongAnswers":"-2.75","reason":"Combines 7 - 3k into 4k (subtracts unlike terms).","feedback":"7 and 3k are not like terms: 7 is an ordinary number and 3k contains k. They can't be combined into 4k. Remove 7 from both sides first."},{"id":27,"chapter":"Ch 3 - Mixed Operations","question":"7 - 3k = -11","correctAnswer":"k = 6","code":"LM","errorType":"Incomplete steps","wrongAnswers":"-18","reason":"Stops at -3k = -18 (not yet divided by -3).","feedback":"Almost done! k is still multiplied by -3. Keep going until k is alone."},{"id":28,"chapter":"Ch 3 - Mixed Operations","question":"2y/5 - 3 = 7","correctAnswer":"y = 25","code":"LM","errorType":"Incomplete steps","wrongAnswers":"50","reason":"Stops at 2y = 50 (not yet divided by 2).","feedback":"You removed the denominator 5, good! But y is still multiplied by 2. Keep going!"},{"id":28,"chapter":"Ch 3 - Mixed Operations","question":"2y/5 - 3 = 7","correctAnswer":"y = 25","code":"KV","errorType":"Multiply/divide confusion","wrongAnswers":"4","reason":"Multiplies 10 by 2/5 (instead of its reciprocal 5/2).","feedback":"To remove the divisor 5, multiply both sides by 5. After that, deal with the 2 in front of y."},{"id":28,"chapter":"Ch 3 - Mixed Operations","question":"2y/5 - 3 = 7","correctAnswer":"y = 25","code":"PR","errorType":"Transposition error","wrongAnswers":"10","reason":"Moves -3 without changing its sign (2y/5 = 7 - 3).","feedback":"When - 3 moves to the right side, its sign changes. Try your first step again."},{"id":28,"chapter":"Ch 3 - Mixed Operations","question":"2y/5 - 3 = 7","correctAnswer":"y = 25","code":"HT","errorType":"Calculation error","wrongAnswers":"20 or 30","reason":"The steps are correct (2y = 50), but 50 : 2 is miscalculated.","feedback":"Your steps are right! Just double-check the result of 50 : 2."},{"id":29,"chapter":"Ch 3 - Mixed Operations","question":"3(2n + 1) = 27","correctAnswer":"n = 4","code":"DS","errorType":"Distribution (expanding brackets) error","wrongAnswers":"13/3 (≈ 4.33)","reason":"Expands 3(2n + 1) as 6n + 1: the 1 is not multiplied by 3.","feedback":"Remember: the number in front of the brackets multiplies EVERYTHING inside. Try multiplying 3 by 2n, then 3 by 1."},{"id":29,"chapter":"Ch 3 - Mixed Operations","question":"3(2n + 1) = 27","correctAnswer":"n = 4","code":"LM","errorType":"Incomplete steps","wrongAnswers":"8","reason":"Stops at 2n = 8 (not yet divided by 2).","feedback":"You removed + 1, good! But n is still multiplied by 2. Keep going!"},{"id":29,"chapter":"Ch 3 - Mixed Operations","question":"3(2n + 1) = 27","correctAnswer":"n = 4","code":"LM","errorType":"Incomplete steps","wrongAnswers":"9","reason":"Stops at 2n + 1 = 9 (not yet removing + 1 and the 2).","feedback":"You got rid of the 3 in front of the brackets, good! But n still has + 1 with it and is multiplied by 2. Keep going!"},{"id":29,"chapter":"Ch 3 - Mixed Operations","question":"3(2n + 1) = 27","correctAnswer":"n = 4","code":"PR","errorType":"Transposition error","wrongAnswers":"5","reason":"Moves + 1 without changing its sign (2n = 9 + 1).","feedback":"When + 1 moves to the right side, its sign changes. Try your steps again."},{"id":30,"chapter":"Ch 3 - Mixed Operations","question":"10 - 2(x + 3) = 2","correctAnswer":"x = 1","code":"DS","errorType":"Distribution (expanding brackets) error","wrongAnswers":"7","reason":"Expands -2(x + 3) as -2x + 6: the negative sign is not multiplied through.","feedback":"Check the sign when expanding the brackets: is -2 times + 3 positive or negative?"},{"id":30,"chapter":"Ch 3 - Mixed Operations","question":"10 - 2(x + 3) = 2","correctAnswer":"x = 1","code":"DS","errorType":"Distribution (expanding brackets) error","wrongAnswers":"2.5","reason":"Expands -2(x + 3) as -2x - 3: the 3 is not multiplied by 2.","feedback":"Remember: the number in front of the brackets (including its sign) multiplies EVERYTHING inside. Try multiplying -2 by x, then -2 by 3."},{"id":30,"chapter":"Ch 3 - Mixed Operations","question":"10 - 2(x + 3) = 2","correctAnswer":"x = 1","code":"GS","errorType":"Combining unlike terms","wrongAnswers":"-2.75","reason":"Computes 10 - 2 = 8 first, giving 8(x + 3) = 2.","feedback":"Be careful with the order of operations: 2(x + 3) must be worked out first (multiplication) before it is subtracted from 10."},{"id":30,"chapter":"Ch 3 - Mixed Operations","question":"10 - 2(x + 3) = 2","correctAnswer":"x = 1","code":"TD","errorType":"Sign / order error","wrongAnswers":"-1","reason":"Turns -2x = -2 into x = -1: thinks a negative divided by a negative is negative.","feedback":"Your steps are good! Check the sign in the last step: is a negative number divided by a negative number positive or negative?"},{"id":31,"chapter":"Ch 4 - Variables on Both Sides","question":"5x - 3 = 2x + 9","correctAnswer":"x = 4","code":"PR","errorType":"Transposition error","wrongAnswers":"2","reason":"5x - 2x = 9 - 3: moves -3 without changing its sign.","feedback":"When - 3 moves to the right side, its sign changes. - 3 on the left becomes ... on the right. Try again."},{"id":31,"chapter":"Ch 4 - Variables on Both Sides","question":"5x - 3 = 2x + 9","correctAnswer":"x = 4","code":"PR","errorType":"Transposition error","wrongAnswers":"12/7 (≈ 1.71)","reason":"5x + 2x = 9 + 3: moves 2x without changing its sign.","feedback":"When 2x moves to the left side, its sign changes too. + 2x on the right becomes ... on the left. Try again."},{"id":31,"chapter":"Ch 4 - Variables on Both Sides","question":"5x - 3 = 2x + 9","correctAnswer":"x = 4","code":"LM","errorType":"Incomplete steps","wrongAnswers":"12","reason":"Stops at 3x = 12 (not yet divided by 3).","feedback":"You managed to gather the terms, great! But x is still multiplied by 3. Keep going!"},{"id":31,"chapter":"Ch 4 - Variables on Both Sides","question":"5x - 3 = 2x + 9","correctAnswer":"x = 4","code":"HT","errorType":"Calculation error","wrongAnswers":"3 or 5","reason":"The steps are correct (12 : 3), but the division result is miscalculated.","feedback":"Your steps are right! Just double-check the result of 12 : 3."},{"id":32,"chapter":"Ch 4 - Variables on Both Sides","question":"7y + 4 = 3y - 12","correctAnswer":"y = -4","code":"PR","errorType":"Transposition error","wrongAnswers":"-2","reason":"7y - 3y = -12 + 4: moves + 4 without changing its sign.","feedback":"When + 4 moves to the right side, its sign changes. Try your moving step again."},{"id":32,"chapter":"Ch 4 - Variables on Both Sides","question":"7y + 4 = 3y - 12","correctAnswer":"y = -4","code":"PR","errorType":"Transposition error","wrongAnswers":"-1.6","reason":"7y + 3y = -12 - 4: moves 3y without changing its sign.","feedback":"When 3y moves to the left side, its sign changes too. + 3y on the right becomes ... on the left."},{"id":32,"chapter":"Ch 4 - Variables on Both Sides","question":"7y + 4 = 3y - 12","correctAnswer":"y = -4","code":"TD","errorType":"Sign / order error","wrongAnswers":"4","reason":"Divides -16 : 4 but writes the result as positive: the negative sign is lost.","feedback":"You divided, good! Check the sign: is -16 divided by 4 positive or negative?"},{"id":32,"chapter":"Ch 4 - Variables on Both Sides","question":"7y + 4 = 3y - 12","correctAnswer":"y = -4","code":"LM","errorType":"Incomplete steps","wrongAnswers":"-16","reason":"Stops at 4y = -16 (not yet divided by 4).","feedback":"You managed to gather the terms, great! But y is still multiplied by 4. Keep going!"},{"id":33,"chapter":"Ch 4 - Variables on Both Sides","question":"4a + 10 = 6a - 2","correctAnswer":"a = 6","code":"PR","errorType":"Transposition error","wrongAnswers":"-4","reason":"4a - 6a = -2 + 10: moves + 10 without changing its sign.","feedback":"When + 10 moves to the right side, its sign changes. Try your moving step again."},{"id":33,"chapter":"Ch 4 - Variables on Both Sides","question":"4a + 10 = 6a - 2","correctAnswer":"a = 6","code":"PR","errorType":"Transposition error","wrongAnswers":"-1.2","reason":"4a + 6a = -2 - 10: moves 6a without changing its sign.","feedback":"When 6a moves to the left side, its sign changes too. + 6a on the right becomes ... on the left."},{"id":33,"chapter":"Ch 4 - Variables on Both Sides","question":"4a + 10 = 6a - 2","correctAnswer":"a = 6","code":"TD","errorType":"Sign / order error","wrongAnswers":"-6","reason":"Turns -2a = -12 into a = -6: thinks a negative divided by a negative is negative.","feedback":"Your steps are good! Check the sign in the last step: is a negative number divided by a negative number positive or negative?"},{"id":33,"chapter":"Ch 4 - Variables on Both Sides","question":"4a + 10 = 6a - 2","correctAnswer":"a = 6","code":"LM","errorType":"Incomplete steps","wrongAnswers":"12","reason":"Stops at 2a = 12 (not yet divided by 2).","feedback":"You managed to gather the terms, great! But a is still multiplied by 2. Keep going!"},{"id":34,"chapter":"Ch 4 - Variables on Both Sides","question":"3(m + 2) = 2(m + 7)","correctAnswer":"m = 8","code":"DS","errorType":"Distribution (expanding brackets) error","wrongAnswers":"12","reason":"Expands 3(m + 2) as 3m + 2: the 2 is not multiplied by 3.","feedback":"Remember: the number in front of the brackets multiplies EVERYTHING inside. Check BOTH your left side and your right side."},{"id":34,"chapter":"Ch 4 - Variables on Both Sides","question":"3(m + 2) = 2(m + 7)","correctAnswer":"m = 8","code":"DS","errorType":"Distribution (expanding brackets) error","wrongAnswers":"1","reason":"Expands 2(m + 7) as 2m + 7: the 7 is not multiplied by 2.","feedback":"Remember: the number in front of the brackets multiplies EVERYTHING inside. Check BOTH your left side and your right side."},{"id":34,"chapter":"Ch 4 - Variables on Both Sides","question":"3(m + 2) = 2(m + 7)","correctAnswer":"m = 8","code":"TD","errorType":"Sign / order error","wrongAnswers":"-8","reason":"3m - 2m = 6 - 14: the order of subtraction is reversed.","feedback":"Almost! When you move the constant terms, check the order: the number on the right side minus the number that moved over from the left, not the other way around."},{"id":34,"chapter":"Ch 4 - Variables on Both Sides","question":"3(m + 2) = 2(m + 7)","correctAnswer":"m = 8","code":"PR","errorType":"Transposition error","wrongAnswers":"4","reason":"3m + 2m = 14 + 6: moves 6 and 2m without changing their signs.","feedback":"When terms move to the other side, their signs change. Check the signs of 6 and 2m after you moved them."},{"id":34,"chapter":"Ch 4 - Variables on Both Sides","question":"3(m + 2) = 2(m + 7)","correctAnswer":"m = 8","code":"HT","errorType":"Calculation error","wrongAnswers":"7 or 9","reason":"The steps are correct (14 - 6), but the result is miscalculated.","feedback":"Your steps are right! Just double-check the result of 14 - 6."},{"id":35,"chapter":"Ch 4 - Variables on Both Sides","question":"8 - 2p = 4p + 20","correctAnswer":"p = -2","code":"TD","errorType":"Sign / order error","wrongAnswers":"2","reason":"Divides -12 : 6 but writes the result as positive: the negative sign is lost.","feedback":"You divided, good! Check the sign: is -12 divided by 6 positive or negative?"},{"id":35,"chapter":"Ch 4 - Variables on Both Sides","question":"8 - 2p = 4p + 20","correctAnswer":"p = -2","code":"PR","errorType":"Transposition error","wrongAnswers":"-14/3 (≈ -4.67)","reason":"-2p - 4p = 20 + 8: moves 8 without changing its sign.","feedback":"When 8 moves to the right side, its sign changes. + 8 on the left becomes ... on the right."},{"id":35,"chapter":"Ch 4 - Variables on Both Sides","question":"8 - 2p = 4p + 20","correctAnswer":"p = -2","code":"PR","errorType":"Transposition error","wrongAnswers":"6","reason":"8 - 2p + 4p = 20: moves 4p without changing its sign.","feedback":"When 4p moves to the left side, its sign changes too. + 4p on the right becomes ... on the left."},{"id":35,"chapter":"Ch 4 - Variables on Both Sides","question":"8 - 2p = 4p + 20","correctAnswer":"p = -2","code":"LM","errorType":"Incomplete steps","wrongAnswers":"-12","reason":"Stops at -12 = 6p (not yet divided by 6).","feedback":"You managed to gather the terms, great! But p is still multiplied by 6. Keep going!"},{"id":35,"chapter":"Ch 4 - Variables on Both Sides","question":"8 - 2p = 4p + 20","correctAnswer":"p = -2","code":"GS","errorType":"Combining unlike terms","wrongAnswers":"10","reason":"Combines 8 - 2p into 6p (subtracts unlike terms).","feedback":"8 and 2p are not like terms: 8 is an ordinary number and 2p contains p. They can't be combined into 6p."},{"id":36,"chapter":"Ch 4 - Variables on Both Sides","question":"6k - 5 = 2k + 15","correctAnswer":"k = 5","code":"PR","errorType":"Transposition error","wrongAnswers":"2.5","reason":"6k - 2k = 15 - 5: moves - 5 without changing its sign.","feedback":"When - 5 moves to the right side, its sign changes. Try your moving step again."},{"id":36,"chapter":"Ch 4 - Variables on Both Sides","question":"6k - 5 = 2k + 15","correctAnswer":"k = 5","code":"PR","errorType":"Transposition error","wrongAnswers":"1.25","reason":"6k + 2k = 15 - 5: moves 2k and - 5 without changing their signs.","feedback":"When terms move to the other side, their signs change. Check the signs of 2k and 5 after you moved them."},{"id":36,"chapter":"Ch 4 - Variables on Both Sides","question":"6k - 5 = 2k + 15","correctAnswer":"k = 5","code":"LM","errorType":"Incomplete steps","wrongAnswers":"20","reason":"Stops at 4k = 20 (not yet divided by 4).","feedback":"You managed to gather the terms, great! But k is still multiplied by 4. Keep going!"},{"id":36,"chapter":"Ch 4 - Variables on Both Sides","question":"6k - 5 = 2k + 15","correctAnswer":"k = 5","code":"KV","errorType":"Multiply/divide confusion","wrongAnswers":"80","reason":"Multiplies 20 x 4 (instead of dividing).","feedback":"4k means 4 times k. To get k alone, which operation is the opposite of multiplying?"},{"id":36,"chapter":"Ch 4 - Variables on Both Sides","question":"6k - 5 = 2k + 15","correctAnswer":"k = 5","code":"HT","errorType":"Calculation error","wrongAnswers":"4 or 6","reason":"The steps are correct (20 : 4), but the division result is miscalculated.","feedback":"Your steps are right! Just double-check the result of 20 : 4."},{"id":37,"chapter":"Ch 4 - Variables on Both Sides","question":"(1/2)x + 3 = (1/4)x + 5","correctAnswer":"x = 8","code":"KV","errorType":"Multiply/divide confusion","wrongAnswers":"0.5","reason":"Multiplies 2 x 1/4: uses the same fraction instead of its reciprocal.","feedback":"The coefficient of x is 1/4. To get x alone, multiply by the RECIPROCAL of 1/4."},{"id":37,"chapter":"Ch 4 - Variables on Both Sides","question":"(1/2)x + 3 = (1/4)x + 5","correctAnswer":"x = 8","code":"PC","errorType":"Fraction / decimal error","wrongAnswers":"-4","reason":"Subtracts 1/2 - 1/4 by subtracting the denominators (1/(2 - 4) = -1/2), giving - 1/2 x = 2.","feedback":"Fractions are not subtracted by subtracting the denominators! First make the denominators the same (turn them into quarters), then subtract the numerators."},{"id":37,"chapter":"Ch 4 - Variables on Both Sides","question":"(1/2)x + 3 = (1/4)x + 5","correctAnswer":"x = 8","code":"PR","errorType":"Transposition error","wrongAnswers":"8/3 (≈ 2.67)","reason":"1/2 x + 1/4 x = 2: moves 1/4 x without changing its sign.","feedback":"When 1/4 x moves to the left side, its sign changes too. + 1/4 x on the right becomes ... on the left."},{"id":37,"chapter":"Ch 4 - Variables on Both Sides","question":"(1/2)x + 3 = (1/4)x + 5","correctAnswer":"x = 8","code":"PR","errorType":"Transposition error","wrongAnswers":"32","reason":"1/2 x - 1/4 x = 5 + 3: moves + 3 without changing its sign.","feedback":"When + 3 moves to the right side, its sign changes. + 3 on the left becomes ... on the right."},{"id":37,"chapter":"Ch 4 - Variables on Both Sides","question":"(1/2)x + 3 = (1/4)x + 5","correctAnswer":"x = 8","code":"LM","errorType":"Incomplete steps","wrongAnswers":"2","reason":"Stops at 1/4 x = 2 (not yet multiplied by 4).","feedback":"You managed to gather the terms, great! But x is still multiplied by 1/4. Keep going!"},{"id":38,"chapter":"Ch 4 - Variables on Both Sides","question":"5(n - 1) = 3(n + 3)","correctAnswer":"n = 7","code":"DS","errorType":"Distribution (expanding brackets) error","wrongAnswers":"5","reason":"Expands 5(n - 1) as 5n - 1: the 1 is not multiplied by 5.","feedback":"Remember: the number in front of the brackets multiplies EVERYTHING inside. Check BOTH your left side and your right side."},{"id":38,"chapter":"Ch 4 - Variables on Both Sides","question":"5(n - 1) = 3(n + 3)","correctAnswer":"n = 7","code":"DS","errorType":"Distribution (expanding brackets) error","wrongAnswers":"4","reason":"Expands 3(n + 3) as 3n + 3: the second 3 is not multiplied by 3.","feedback":"Remember: the number in front of the brackets multiplies EVERYTHING inside. Check BOTH your left side and your right side."},{"id":38,"chapter":"Ch 4 - Variables on Both Sides","question":"5(n - 1) = 3(n + 3)","correctAnswer":"n = 7","code":"DS","errorType":"Distribution (expanding brackets) error","wrongAnswers":"2","reason":"Expands 5(n - 1) as 5n + 5: the negative sign is lost when multiplying.","feedback":"Check the sign when expanding the brackets: is 5 x (-1) positive or negative?"},{"id":38,"chapter":"Ch 4 - Variables on Both Sides","question":"5(n - 1) = 3(n + 3)","correctAnswer":"n = 7","code":"PR","errorType":"Transposition error","wrongAnswers":"0.5","reason":"5n + 3n = 9 - 5: moves 3n and - 5 without changing their signs.","feedback":"When terms move to the other side, their signs change. Check the signs of 3n and 5 after you moved them."},{"id":38,"chapter":"Ch 4 - Variables on Both Sides","question":"5(n - 1) = 3(n + 3)","correctAnswer":"n = 7","code":"HT","errorType":"Calculation error","wrongAnswers":"6 or 8","reason":"The steps are correct (14 : 2), but the division result is miscalculated.","feedback":"Your steps are right! Just double-check the result of 14 : 2."},{"id":39,"chapter":"Ch 4 - Variables on Both Sides","question":"9x - (2x + 5) = 3x + 11","correctAnswer":"x = 4","code":"DS","errorType":"Distribution (expanding brackets) error","wrongAnswers":"1.5","reason":"Expands -(2x + 5) as - 2x + 5: the sign of 5 doesn't change.","feedback":"The minus sign in front of the brackets applies to EVERYTHING inside, including 5. Try expanding the brackets once more."},{"id":39,"chapter":"Ch 4 - Variables on Both Sides","question":"9x - (2x + 5) = 3x + 11","correctAnswer":"x = 4","code":"DS","errorType":"Distribution (expanding brackets) error","wrongAnswers":"2","reason":"Expands -(2x + 5) as + 2x - 5: the sign of 2x doesn't change.","feedback":"The minus sign in front of the brackets applies to EVERYTHING inside, including 2x. Try expanding the brackets once more."},{"id":39,"chapter":"Ch 4 - Variables on Both Sides","question":"9x - (2x + 5) = 3x + 11","correctAnswer":"x = 4","code":"LM","errorType":"Incomplete steps","wrongAnswers":"16","reason":"Stops at 4x = 16 (not yet divided by 4).","feedback":"You managed to gather the terms, great! But x is still multiplied by 4. Keep going!"},{"id":39,"chapter":"Ch 4 - Variables on Both Sides","question":"9x - (2x + 5) = 3x + 11","correctAnswer":"x = 4","code":"HT","errorType":"Calculation error","wrongAnswers":"3 or 5","reason":"The steps are correct (16 : 4), but the division result is miscalculated.","feedback":"Your steps are right! Just double-check the result of 16 : 4."},{"id":40,"chapter":"Ch 4 - Variables on Both Sides","question":"4(2z - 1) = 2(3z + 5)","correctAnswer":"z = 7","code":"DS","errorType":"Distribution (expanding brackets) error","wrongAnswers":"5.5","reason":"Expands 4(2z - 1) as 8z - 1: the 1 is not multiplied by 4.","feedback":"Remember: the number in front of the brackets multiplies EVERYTHING inside. Check BOTH your left side and your right side."},{"id":40,"chapter":"Ch 4 - Variables on Both Sides","question":"4(2z - 1) = 2(3z + 5)","correctAnswer":"z = 7","code":"DS","errorType":"Distribution (expanding brackets) error","wrongAnswers":"4.5","reason":"Expands 2(3z + 5) as 6z + 5: the 5 is not multiplied by 2.","feedback":"Remember: the number in front of the brackets multiplies EVERYTHING inside. Check BOTH your left side and your right side."},{"id":40,"chapter":"Ch 4 - Variables on Both Sides","question":"4(2z - 1) = 2(3z + 5)","correctAnswer":"z = 7","code":"DS","errorType":"Distribution (expanding brackets) error","wrongAnswers":"3","reason":"Expands 4(2z - 1) as 8z + 4: the negative sign is lost when multiplying.","feedback":"Check the sign when expanding the brackets: is 4 x (-1) positive or negative?"},{"id":40,"chapter":"Ch 4 - Variables on Both Sides","question":"4(2z - 1) = 2(3z + 5)","correctAnswer":"z = 7","code":"PR","errorType":"Transposition error","wrongAnswers":"1","reason":"8z + 6z - 4 = 10: moves 6z without changing its sign.","feedback":"When 6z moves to the left side, its sign changes. + 6z on the right becomes ... on the left."},{"id":40,"chapter":"Ch 4 - Variables on Both Sides","question":"4(2z - 1) = 2(3z + 5)","correctAnswer":"z = 7","code":"LM","errorType":"Incomplete steps","wrongAnswers":"14","reason":"Stops at 2z = 14 (not yet divided by 2).","feedback":"You managed to gather the terms, great! But z is still multiplied by 2. Keep going!"},{"id":41,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Parang Batik Cloth - Java) The price of 3 pieces of Parang batik cloth after a Rp20,000 voucher discount is Rp250,000. What is the original price of 1 piece of Parang batik cloth?","correctAnswer":"Rp90,000","code":"MP","errorType":"Wrong equation model (word problem)","wrongAnswers":"Rp83,333.33","reason":"Ignores the discount: 250,000 : 3.","feedback":"Read again: Rp250,000 is the price AFTER the discount, so the original price is higher. How would you write 'original price of 3 pieces minus discount = 250,000' as an equation?"},{"id":41,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Parang Batik Cloth - Java) The price of 3 pieces of Parang batik cloth after a Rp20,000 voucher discount is Rp250,000. What is the original price of 1 piece of Parang batik cloth?","correctAnswer":"Rp90,000","code":"MP","errorType":"Wrong equation model (word problem)","wrongAnswers":"Rp76,666.67","reason":"Subtracts the discount from the final price: (250,000 - 20,000) : 3.","feedback":"The price after the discount is lower than the original price. To go back to the original price, what should you do with the discount: subtract it again or give it back?"},{"id":41,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Parang Batik Cloth - Java) The price of 3 pieces of Parang batik cloth after a Rp20,000 voucher discount is Rp250,000. What is the original price of 1 piece of Parang batik cloth?","correctAnswer":"Rp90,000","code":"MP","errorType":"Wrong equation model (word problem)","wrongAnswers":"Rp103,333.33","reason":"Thinks the discount applies per piece: x - 20,000 = 250,000 : 3.","feedback":"The Rp20,000 discount applies to the whole purchase (3 pieces), not to each piece. In which part of your equation should the discount be written?"},{"id":41,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Parang Batik Cloth - Java) The price of 3 pieces of Parang batik cloth after a Rp20,000 voucher discount is Rp250,000. What is the original price of 1 piece of Parang batik cloth?","correctAnswer":"Rp90,000","code":"LM","errorType":"Incomplete steps","wrongAnswers":"Rp270,000","reason":"Stops at 3x = 270,000 (original price of 3 pieces), forgetting to divide by 3.","feedback":"Great, your equation is right! But 270,000 is the original price for 3 pieces. The question asks for the original price of 1 piece."},{"id":42,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Borobudur Temple - Central Java) The lower tier has 15 more stones than the upper tier. If the two tiers have 85 stones in total, how many stones are on the upper tier?","correctAnswer":"35 stones","code":"MP","errorType":"Wrong equation model (word problem)","wrongAnswers":"42.5","reason":"Divides the total 85 : 2: assumes both tiers have the same number of stones.","feedback":"The two tiers do not have the same number of stones! The lower tier has 15 more. If the upper tier = x, how do you write the stones in the lower tier?"},{"id":42,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Borobudur Temple - Central Java) The lower tier has 15 more stones than the upper tier. If the two tiers have 85 stones in total, how many stones are on the upper tier?","correctAnswer":"35 stones","code":"PT","errorType":"Answers a different quantity","wrongAnswers":"50","reason":"Answers the number of stones in the lower tier, or models upper = lower + 15.","feedback":"Check the question: are you asked for the upper or the lower tier? Also check which one has more, the upper or the lower?"},{"id":42,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Borobudur Temple - Central Java) The lower tier has 15 more stones than the upper tier. If the two tiers have 85 stones in total, how many stones are on the upper tier?","correctAnswer":"35 stones","code":"LM","errorType":"Incomplete steps","wrongAnswers":"70","reason":"Stops at 2x = 70 (not yet divided by 2).","feedback":"You dealt with + 15, good! But 2x is not the answer: x is still multiplied by 2. Keep going!"},{"id":43,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Angklung - West Java) A large angklung costs Rp15,000 more than a small angklung. A buyer pays Rp105,000 for 2 small angklungs and 1 large angklung. What is the price of 1 small angklung?","correctAnswer":"Rp30,000","code":"PT","errorType":"Answers a different quantity","wrongAnswers":"Rp45,000","reason":"Answers the price of the large angklung (x + 15,000).","feedback":"You found the price of one of the angklungs, but check the question: is it asking for the small or the large angklung?"},{"id":43,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Angklung - West Java) A large angklung costs Rp15,000 more than a small angklung. A buyer pays Rp105,000 for 2 small angklungs and 1 large angklung. What is the price of 1 small angklung?","correctAnswer":"Rp30,000","code":"MP","errorType":"Wrong equation model (word problem)","wrongAnswers":"Rp35,000","reason":"Divides 105,000 : 3: assumes all three angklungs cost the same.","feedback":"The large angklung is not the same price as the small one (it is Rp15,000 more expensive). Don't ignore that difference when setting up your equation."},{"id":43,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Angklung - West Java) A large angklung costs Rp15,000 more than a small angklung. A buyer pays Rp105,000 for 2 small angklungs and 1 large angklung. What is the price of 1 small angklung?","correctAnswer":"Rp30,000","code":"MP","errorType":"Wrong equation model (word problem)","wrongAnswers":"Rp25,000","reason":"Writes 2(x + 15,000) + x = 105,000: the part multiplied by 2 is swapped.","feedback":"The buyer bought 2 SMALL angklungs and 1 LARGE angklung. Check again which part is multiplied by 2."},{"id":43,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Angklung - West Java) A large angklung costs Rp15,000 more than a small angklung. A buyer pays Rp105,000 for 2 small angklungs and 1 large angklung. What is the price of 1 small angklung?","correctAnswer":"Rp30,000","code":"MP","errorType":"Wrong equation model (word problem)","wrongAnswers":"Rp40,000","reason":"Adds the difference: (105,000 + 15,000) : 3.","feedback":"The Rp15,000 difference only applies to the large angklung. From the total, that difference must be removed first (subtracted), not added."},{"id":43,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Angklung - West Java) A large angklung costs Rp15,000 more than a small angklung. A buyer pays Rp105,000 for 2 small angklungs and 1 large angklung. What is the price of 1 small angklung?","correctAnswer":"Rp30,000","code":"LM","errorType":"Incomplete steps","wrongAnswers":"Rp90,000","reason":"Stops at 3x = 90,000 (not yet divided by 3).","feedback":"Great, your equation is right! But 90,000 is for 3 small angklungs. What is the price of 1 small angklung?"},{"id":44,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Rumah Gadang - West Sumatra) A wall carving is a rectangle with length (2x + 3) cm and width x cm. If its perimeter is 54 cm, what is the value of x?","correctAnswer":"x = 8","code":"MP","errorType":"Wrong equation model (word problem)","wrongAnswers":"17","reason":"Uses perimeter = length + width (forgets to multiply by 2).","feedback":"The perimeter of a rectangle = 2 x (length + width). Rewrite your equation using the complete perimeter formula."},{"id":44,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Rumah Gadang - West Sumatra) A wall carving is a rectangle with length (2x + 3) cm and width x cm. If its perimeter is 54 cm, what is the value of x?","correctAnswer":"x = 8","code":"MP","errorType":"Wrong equation model (word problem)","wrongAnswers":"9.6","reason":"Uses perimeter = 2 x length + width (the 2 only multiplies the length).","feedback":"In perimeter = 2 x (length + width), the 2 multiplies BOTH. Check the brackets in your equation."},{"id":44,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Rumah Gadang - West Sumatra) A wall carving is a rectangle with length (2x + 3) cm and width x cm. If its perimeter is 54 cm, what is the value of x?","correctAnswer":"x = 8","code":"DS","errorType":"Distribution (expanding brackets) error","wrongAnswers":"8.5","reason":"Expands 2(3x + 3) as 6x + 3: the 3 is not multiplied by 2.","feedback":"The 2 in front of the brackets must multiply both terms inside, including the 3."},{"id":44,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Rumah Gadang - West Sumatra) A wall carving is a rectangle with length (2x + 3) cm and width x cm. If its perimeter is 54 cm, what is the value of x?","correctAnswer":"x = 8","code":"LM","errorType":"Incomplete steps","wrongAnswers":"24","reason":"Stops at 3x = 24 (not yet divided by 3).","feedback":"Your equation is right and you're almost there! But x is still multiplied by 3. Keep going!"},{"id":45,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Lupis Cake - Java) Mother buys 5 packs of lupis cake and hands over Rp50,000. Her change is Rp15,000. What is the price of 1 pack of lupis cake?","correctAnswer":"Rp7,000","code":"MP","errorType":"Wrong equation model (word problem)","wrongAnswers":"Rp13,000","reason":"Adds the change: (50,000 + 15,000) : 5.","feedback":"Mother handed over Rp50,000, then part of it came back. So the price of 5 packs = the money given ... the change. Rewrite your equation."},{"id":45,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Lupis Cake - Java) Mother buys 5 packs of lupis cake and hands over Rp50,000. Her change is Rp15,000. What is the price of 1 pack of lupis cake?","correctAnswer":"Rp7,000","code":"MP","errorType":"Wrong equation model (word problem)","wrongAnswers":"Rp10,000","reason":"Ignores the change: 50,000 : 5.","feedback":"Mother did not spend all of the Rp50,000: there is Rp15,000 in change. Include the change in your equation."},{"id":45,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Lupis Cake - Java) Mother buys 5 packs of lupis cake and hands over Rp50,000. Her change is Rp15,000. What is the price of 1 pack of lupis cake?","correctAnswer":"Rp7,000","code":"MP","errorType":"Wrong equation model (word problem)","wrongAnswers":"Rp3,000","reason":"Uses only the change: 15,000 : 5.","feedback":"Rp15,000 is the change, not the price of the cakes. The price of the cakes is the money actually paid. How much is that?"},{"id":45,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Lupis Cake - Java) Mother buys 5 packs of lupis cake and hands over Rp50,000. Her change is Rp15,000. What is the price of 1 pack of lupis cake?","correctAnswer":"Rp7,000","code":"LM","errorType":"Incomplete steps","wrongAnswers":"Rp35,000","reason":"Stops at 5x = 35,000 (price of 5 packs), forgetting to divide by 5.","feedback":"Great, your equation is right! But 35,000 is the price of 5 packs. The question asks for the price of 1 pack."},{"id":45,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Lupis Cake - Java) Mother buys 5 packs of lupis cake and hands over Rp50,000. Her change is Rp15,000. What is the price of 1 pack of lupis cake?","correctAnswer":"Rp7,000","code":"HT","errorType":"Calculation error","wrongAnswers":"Rp6,000 or Rp8,000","reason":"The steps are correct (35,000 : 5), but the division result is miscalculated.","feedback":"Your steps are right! Just double-check the result of 35,000 : 5."},{"id":46,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Keris - Nusantara) The Luk 5 keris is 8 cm longer than the Luk 3 keris. The total length of the two keris side by side is 72 cm. What is the length of the Luk 3 keris?","correctAnswer":"32 cm","code":"MP","errorType":"Wrong equation model (word problem)","wrongAnswers":"36","reason":"Divides the total 72 : 2: assumes both keris are the same length.","feedback":"The Luk 5 keris is 8 cm longer than the Luk 3 keris. If Luk 3 = x, how do you write the length of Luk 5?"},{"id":46,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Keris - Nusantara) The Luk 5 keris is 8 cm longer than the Luk 3 keris. The total length of the two keris side by side is 72 cm. What is the length of the Luk 3 keris?","correctAnswer":"32 cm","code":"PT","errorType":"Answers a different quantity","wrongAnswers":"40","reason":"Answers the length of the Luk 5 keris, or models Luk 3 = Luk 5 + 8.","feedback":"Check the question: are you asked for Luk 3 or Luk 5? And which one is longer?"},{"id":46,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Keris - Nusantara) The Luk 5 keris is 8 cm longer than the Luk 3 keris. The total length of the two keris side by side is 72 cm. What is the length of the Luk 3 keris?","correctAnswer":"32 cm","code":"LM","errorType":"Incomplete steps","wrongAnswers":"64","reason":"Stops at 2x = 64 (not yet divided by 2).","feedback":"Your equation is right and you're almost there! But x is still multiplied by 2. Keep going!"},{"id":46,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Keris - Nusantara) The Luk 5 keris is 8 cm longer than the Luk 3 keris. The total length of the two keris side by side is 72 cm. What is the length of the Luk 3 keris?","correctAnswer":"32 cm","code":"HT","errorType":"Calculation error","wrongAnswers":"31 or 33","reason":"The steps are correct (64 : 2), but the division result is miscalculated.","feedback":"Your steps are right! Just double-check the result of 64 : 2."},{"id":47,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Congklak) Budi has 3 times as many seeds as Ani. If Budi gives 10 seeds to Ani, they have the same number of seeds. How many seeds does Ani have at the start of the game?","correctAnswer":"10 seeds","code":"PT","errorType":"Answers a different quantity","wrongAnswers":"30","reason":"Answers the number of Budi's seeds before giving (3x).","feedback":"You found x correctly! But check the question: is it asking for Ani's seeds or Budi's seeds?"},{"id":47,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Congklak) Budi has 3 times as many seeds as Ani. If Budi gives 10 seeds to Ani, they have the same number of seeds. How many seeds does Ani have at the start of the game?","correctAnswer":"10 seeds","code":"MP","errorType":"Wrong equation model (word problem)","wrongAnswers":"5","reason":"Writes 3x - 10 = x: forgets that Ani receives 10 seeds.","feedback":"When Budi gives away 10 seeds, Ani's seeds change too. How do you write Ani's seeds after receiving 10?"},{"id":47,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Congklak) Budi has 3 times as many seeds as Ani. If Budi gives 10 seeds to Ani, they have the same number of seeds. How many seeds does Ani have at the start of the game?","correctAnswer":"10 seeds","code":"MP","errorType":"Wrong equation model (word problem)","wrongAnswers":"-10","reason":"Writes 3x + 10 = x - 10: the giver and the receiver are swapped.","feedback":"Budi GIVES 10 seeds (his seeds decrease), Ani RECEIVES them (her seeds increase). Check the signs on both sides of your equation."},{"id":47,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Congklak) Budi has 3 times as many seeds as Ani. If Budi gives 10 seeds to Ani, they have the same number of seeds. How many seeds does Ani have at the start of the game?","correctAnswer":"10 seeds","code":"LM","errorType":"Incomplete steps","wrongAnswers":"20","reason":"Stops at 2x = 20 (not yet divided by 2).","feedback":"Your equation is right and you're almost there! But x is still multiplied by 2. Keep going!"},{"id":48,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Ulos Cloth - North Sumatra) Two Ulos cloths (standard and super) are sold for Rp450,000 in total. The super Ulos is Rp90,000 more expensive than the standard one. What is the price of the standard Ulos?","correctAnswer":"Rp180,000","code":"PT","errorType":"Answers a different quantity","wrongAnswers":"Rp270,000","reason":"Answers the price of the super Ulos, or models standard = super + 90,000.","feedback":"Check the question: are you asked for the standard or the super Ulos? And which one is more expensive?"},{"id":48,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Ulos Cloth - North Sumatra) Two Ulos cloths (standard and super) are sold for Rp450,000 in total. The super Ulos is Rp90,000 more expensive than the standard one. What is the price of the standard Ulos?","correctAnswer":"Rp180,000","code":"MP","errorType":"Wrong equation model (word problem)","wrongAnswers":"Rp225,000","reason":"Divides the total 450,000 : 2: assumes both Ulos cost the same.","feedback":"The super Ulos costs Rp90,000 more. If the standard Ulos = x, how do you write the price of the super Ulos?"},{"id":48,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Ulos Cloth - North Sumatra) Two Ulos cloths (standard and super) are sold for Rp450,000 in total. The super Ulos is Rp90,000 more expensive than the standard one. What is the price of the standard Ulos?","correctAnswer":"Rp180,000","code":"LM","errorType":"Incomplete steps","wrongAnswers":"Rp360,000","reason":"Stops at 2x = 360,000 (not yet divided by 2).","feedback":"Your equation is right and you're almost there! But x is still multiplied by 2. Keep going!"},{"id":48,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Ulos Cloth - North Sumatra) Two Ulos cloths (standard and super) are sold for Rp450,000 in total. The super Ulos is Rp90,000 more expensive than the standard one. What is the price of the standard Ulos?","correctAnswer":"Rp180,000","code":"HT","errorType":"Calculation error","wrongAnswers":"Rp170,000 or Rp190,000","reason":"The steps are correct (360,000 : 2), but the division result is miscalculated.","feedback":"Your steps are right! Just double-check the result of 360,000 : 2."},{"id":49,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Piring Dance - West Sumatra) The reserve plates are 1/4 of the number of main plates held by the dancer. If there are 25 plates in total, how many main plates are there?","correctAnswer":"20 plates","code":"PT","errorType":"Answers a different quantity","wrongAnswers":"5","reason":"Answers the number of reserve plates (x : 4).","feedback":"You found the number of one type of plate! Check the question: main plates or reserve plates?"},{"id":49,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Piring Dance - West Sumatra) The reserve plates are 1/4 of the number of main plates held by the dancer. If there are 25 plates in total, how many main plates are there?","correctAnswer":"20 plates","code":"MP","errorType":"Wrong equation model (word problem)","wrongAnswers":"6.25","reason":"Computes 25 : 4: assumes reserve = 1/4 of ALL the plates.","feedback":"The reserve plates are 1/4 of the MAIN plates, not of all the plates. If main = x, how do you write the reserve plates?"},{"id":49,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Piring Dance - West Sumatra) The reserve plates are 1/4 of the number of main plates held by the dancer. If there are 25 plates in total, how many main plates are there?","correctAnswer":"20 plates","code":"MP","errorType":"Wrong equation model (word problem)","wrongAnswers":"18.75","reason":"Computes main = 25 - 25/4: the reserve is assumed to be 1/4 of all the plates.","feedback":"The reserve plates are 1/4 of the MAIN plates, not of all the plates. If main = x, how do you write the reserve plates?"},{"id":49,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Piring Dance - West Sumatra) The reserve plates are 1/4 of the number of main plates held by the dancer. If there are 25 plates in total, how many main plates are there?","correctAnswer":"20 plates","code":"MP","errorType":"Wrong equation model (word problem)","wrongAnswers":"100","reason":"Computes 25 x 4: assumes 25 is the number of reserve plates.","feedback":"25 is the number of ALL the plates (main + reserve). Write main and reserve in terms of x, then add them up to make 25."},{"id":49,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Piring Dance - West Sumatra) The reserve plates are 1/4 of the number of main plates held by the dancer. If there are 25 plates in total, how many main plates are there?","correctAnswer":"20 plates","code":"KV","errorType":"Multiply/divide confusion","wrongAnswers":"31.25","reason":"Multiplies 25 x 5/4: uses the same fraction instead of its reciprocal.","feedback":"The coefficient of x is 5/4. To get x alone, multiply by the RECIPROCAL of 5/4."},{"id":49,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Piring Dance - West Sumatra) The reserve plates are 1/4 of the number of main plates held by the dancer. If there are 25 plates in total, how many main plates are there?","correctAnswer":"20 plates","code":"PC","errorType":"Fraction / decimal error","wrongAnswers":"62.5","reason":"Adds x + 1/4 x as 2/5 x (adds the numerators and the denominators separately).","feedback":"Be careful when adding: x + 1/4 x is not 2/5 x. Turn x into 4/4 x first, then add the numerators."},{"id":50,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Sekaten - Yogyakarta) The number of red wajik is 20 fewer than twice the number of white wajik. If there are 80 red wajik, how many white wajik are there?","correctAnswer":"50 pieces","code":"MP","errorType":"Wrong equation model (word problem)","wrongAnswers":"30","reason":"Reads 'fewer than' as addition: 2x + 20 = 80.","feedback":"'20 fewer than twice' means twice x MINUS 20. Rewrite your equation."},{"id":50,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Sekaten - Yogyakarta) The number of red wajik is 20 fewer than twice the number of white wajik. If there are 80 red wajik, how many white wajik are there?","correctAnswer":"50 pieces","code":"LM","errorType":"Incomplete steps","wrongAnswers":"100","reason":"Stops at 2x = 100 (not yet divided by 2), or skips 'twice' (x - 20 = 80).","feedback":"Check your equation: is there a 'twice' for the white wajik? And if so, x is still multiplied by 2, so keep going!"},{"id":50,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Sekaten - Yogyakarta) The number of red wajik is 20 fewer than twice the number of white wajik. If there are 80 red wajik, how many white wajik are there?","correctAnswer":"50 pieces","code":"PT","errorType":"Answers a different quantity","wrongAnswers":"80","reason":"Answers the number of red wajik (already known in the problem).","feedback":"80 is the number of red wajik and it is already known. Check the question: are you asked for white or red wajik?"},{"id":50,"chapter":"Ch 5 - Ethnomathematics Word Problems","question":"(Sekaten - Yogyakarta) The number of red wajik is 20 fewer than twice the number of white wajik. If there are 80 red wajik, how many white wajik are there?","correctAnswer":"50 pieces","code":"HT","errorType":"Calculation error","wrongAnswers":"40 or 60","reason":"The steps are correct (100 : 2), but the division result is miscalculated.","feedback":"Your steps are right! Just double-check the result of 100 : 2."}];

export const FEEDBACK_BANK = FEEDBACK_BANK_ID;

export const FEEDBACK_FALLBACK_ID = ["Coba periksa kembali langkah pengerjaanmu dari awal. Apakah ada operasi atau perhitungan yang keliru?", "Belum tepat. Coba masukkan jawabanmu ke persamaan: apakah ruas kiri dan ruas kanan bernilai sama? Kalau belum, tulis ulang langkahmu satu per satu."];
export const FEEDBACK_FALLBACK_EN = ["Try checking your solution again from the beginning. Is there an operation or calculation that is incorrect?", "Not quite. Try plugging your answer into the equation: are the left and right sides equal? If not, rewrite your steps one by one."];

function cleanBankNumberToken(raw) {
  let value = String(raw ?? '').trim().toLowerCase();
  value = value
    .replace(/^jawaban\s*[:=]\s*/i, '')
    .replace(/^ans(?:wer)?\s*[:=]\s*/i, '')
    .replace(/[≈~].*$/,'')
    .replace(/^[a-z]{1,4}\s*/i, '')
    .replace(/\([^)]*\)/g, '')
    .replace(/\s+/g, '');
  // Strip common unit/currency suffixes while keeping the numeric payload.
  value = value
    .replace(/^rp\s*/i, '')
    .replace(/(buah|pieces|piece|items?|cm|rupiah)$/i, '');
  return value;
}

function parseLocalizedNumber(value) {
  const token = cleanBankNumberToken(value);
  if (!token) return null;

  // Fractions, including localized fractions like "5/3".
  if (/^-?\d+(?:[.,]\d+)?\/-?\d+(?:[.,]\d+)?$/.test(token)) {
    const parts = token.split('/');
    const left = parseLocalizedNumber(parts[0]);
    const right = parseLocalizedNumber(parts[1]);
    if (Number.isFinite(left) && Number.isFinite(right) && right !== 0) {
      return left / right;
    }
  }

  let normalized = token;
  const hasDot = normalized.includes('.');
  const hasComma = normalized.includes(',');

  if (hasDot && hasComma) {
    // Infer the decimal separator from the final separator:
    // 83,333.33 -> English style; 83.333,33 -> Indonesian style.
    const lastDot = normalized.lastIndexOf('.');
    const lastComma = normalized.lastIndexOf(',');
    if (lastDot > lastComma) {
      normalized = normalized.replace(/,/g, '');
    } else {
      normalized = normalized.replace(/\./g, '').replace(',', '.');
    }
  } else if (hasComma) {
    const pieces = normalized.split(',');
    // "83,333" is thousands-grouped; "3,5" is a decimal.
    if (pieces.length === 2 && pieces[1].length !== 3) {
      normalized = normalized.replace(',', '.');
    } else {
      normalized = normalized.replace(/,/g, '');
    }
  } else if ((normalized.match(/\./g) || []).length > 1) {
    normalized = normalized.replace(/\./g, '');
  }

  if (!/^-?\d+(?:\.\d+)?$/.test(normalized)) return null;
  const number = Number(normalized);
  return Number.isFinite(number) ? number : null;
}

export function parseFeedbackBankAnswers(raw) {
  return String(raw ?? '')
    .split(/\s+(?:atau|or)\s+/i)
    .map(part => part.replace(/\([^)]*\)/g, '').trim())
    .map(part => parseLocalizedNumber(part))
    .filter(value => Number.isFinite(value));
}

export function normalizeFeedbackAnswer(raw) {
  const numeric = typeof raw === 'number' ? raw : parseLocalizedNumber(raw);
  if (Number.isFinite(numeric)) {
    return `num:${Math.round(numeric * 1000000) / 1000000}`;
  }
  return `text:${String(raw ?? '').trim().toLowerCase().replace(/\s+/g,'')}`;
}

function buildBankIndex(bank) {
  const index = new Map();
  for (const row of bank) {
    const bucket = index.get(Number(row.id)) || [];
    for (const value of parseFeedbackBankAnswers(row.wrongAnswers)) {
      bucket.push({ ...row, normalizedAnswer: normalizeFeedbackAnswer(value) });
    }
    index.set(Number(row.id), bucket);
  }
  return index;
}

const BANK_INDEX_ID = buildBankIndex(FEEDBACK_BANK_ID);
const BANK_INDEX_EN = buildBankIndex(FEEDBACK_BANK_EN);

export function findFeedbackBankMatch(questionId, playerAnswer, lang='id') {
  const id = Number(questionId);
  if (!Number.isFinite(id)) return null;
  const index = lang === 'en' ? BANK_INDEX_EN : BANK_INDEX_ID;
  const normalized = normalizeFeedbackAnswer(playerAnswer);
  const candidates = index.get(id) || [];
  return candidates.find(item => item.normalizedAnswer === normalized) || null;
}

export function getFeedbackFallback(lang='id', attempt=1) {
  const bank = lang === 'en' ? FEEDBACK_FALLBACK_EN : FEEDBACK_FALLBACK_ID;
  return bank[Math.min(Math.max(Number(attempt) || 1, 1) - 1, bank.length - 1)] || bank[0];
}
